// Создано scripts/ai-metadata.ts из vendor/ai. Не редактировать вручную.
export const aiSources: Readonly<Record<string, string>> = Object.freeze({
  "AGENTS.md": "# AI Tools\n\nВладелец: zavx0z. Репозиторий содержит универсальные файловые/Git функции и\nобщий lazy-вход для встраивания в Завхоз. Перед изменениями читать README.md,\nMIGRATION.md и контракт затрагиваемого инструмента.\n\nФункции не владеют workspace/session, aliases, roots/open, Interpreter context,\nпроцессами, debugger, replay, UI или MCP lifecycle. Их аргументы — обычные пути\nи параметры операции. Политика доступа принадлежит вызывающему хосту.\nНе возвращать старую модель под новыми именами и не добавлять runtime-перенос\nкак скрытый следующий этап.\n\nСохранять реализацию сущности в index.ts, Input/Output в contract/,\nпроверяемые сценарии в spec/. Общие механизмы — у ближайшего владельца shared/.\nНормы структуры согласуются со Storybook Archetypes; Storybook не runtime-зависимость.\nНе добавлять barrel-фасады, второй каталог контрактов, пользовательский import(),\n/v1 или schemaVersion. Изменение поведения сопровождается контрактом и сценарием.\n\nПрямые функции используют права хоста. Встраиваемый dispatch требует явного true\nот доверенной authorize; клиент не может подменять её в input. Не ослаблять\nавторизацию HTTP при упрощении API. Лимиты, конфликты expectedHash, dryRun,\nнеявную рекурсию/перезапись и partial/unknown проверять отдельно. Не называть\nпроверку пути OS sandbox или expectedHash межпроцессной блокировкой.\n\nДо публикации: bun run check, bun test и npm run test:node; явно перечислить\nдоступные среды и реально выполненные проверки. Тесты используют только\nсобственные временные данные. Сохранять безопасные проверки до/после изменения.\n\nИсторию main не переписывать. Публиковать обычный коммит с проверенным текущим\nродителем и fast-forward без force. Не менять другой репозиторий, установленный\nЗавхоз, слушатель, dirty worktree или процесс неявно. Подготовка API, публикация\nна GitHub, адаптация ServiceClient и установка на Mac — разные результаты.\n",
  "filesystem/apply-patch/contract/input.ts": "/** Standalone tool input. Authorization belongs to the calling host. */\nexport interface ApplyPatchInput {\n  /** Absolute directory for the relative paths embedded in the patch. Not a registered workspace. */\n  directory: string\n  /** Begin Patch format; paths cannot escape directory, including through symlinks. */\n  patch: string\n  /** Plan and validate without writing files or creating parents. */\n  dryRun?: boolean\n}\n",
  "filesystem/apply-patch/contract/output.ts": "/** Filesystem paths in results are absolute; no workspace identity is returned. */\nexport interface ApplyPatchOutput {\n  directory: string\n  applied: boolean\n  changes: {operation: \"add\" | \"update\" | \"delete\" | \"move\"; path: string; from?: string; bytes: number}[]\n}\n",
  "filesystem/apply-patch/index.ts": "/**\n * Применяет текстовый patch в явно указанной директории без регистрации workspace.\n * @remarks dryRun ничего не записывает. Нет fuzzy matching или многофайловой транзакции.\n * При PARTIAL_FAILURE сначала проверяют completed и current, а не повторяют запись вслепую.\n * @packageDocumentation\n */\nimport {lstatSync, mkdirSync, writeFileSync, unlinkSync} from \"node:fs\"\nimport {dirname} from \"node:path\"\nimport {object, text, boolean} from \"../../shared/validation.ts\"\nimport {ToolError, asToolError} from \"../../shared/errors.ts\"\nimport {resolvePath} from \"../shared/paths.ts\"\nimport {readWhole, digest, replaceFile, MAX_BYTES} from \"../shared/files.ts\"\nimport {parsePatch, applyHunks} from \"./src/parse.ts\"\nimport {patchPath} from \"./src/paths.ts\"\nimport type {ApplyPatchInput} from \"./contract/input.ts\"\nimport type {ApplyPatchOutput} from \"./contract/output.ts\"\nexport type {ApplyPatchInput} from \"./contract/input.ts\"\nexport type {ApplyPatchOutput} from \"./contract/output.ts\"\n\nexport function applyPatch(input: ApplyPatchInput): ApplyPatchOutput {\n  object(input, [\"directory\", \"patch\", \"dryRun\"])\n  const patch = text(input.patch, \"patch\")\n  const dryRun = boolean(input.dryRun, false, \"dryRun\")\n  if (Buffer.byteLength(patch) > MAX_BYTES) throw new ToolError(\"LIMIT_EXCEEDED\", \"Patch exceeds the byte limit\", 413)\n  const directory = resolvePath(input.directory)\n  if (!lstatSync(directory).isDirectory()) throw new ToolError(\"INVALID_PATH_TYPE\", \"directory must be a directory\")\n  const operations = parsePatch(patch)\n  const touched = new Set<string>()\n  let totalBytes = 0\n  const planned = operations.map(operation => {\n    const path = patchPath(directory, operation.path, operation.kind === \"add\")\n    const target = operation.kind === \"update\" && operation.to !== undefined ? patchPath(directory, operation.to, true) : path\n    if (touched.has(path) || (target !== path && touched.has(target))) throw new ToolError(\"PATCH_REJECTED\", \"Patch touches a path more than once\", 409)\n    touched.add(path)\n    touched.add(target)\n    if (operation.kind === \"add\" || target !== path) {\n      try {\n        lstatSync(target)\n        throw new ToolError(\"CONFLICT\", \"Patch destination already exists\", 409)\n      } catch (error) { if ((error as NodeJS.ErrnoException).code !== \"ENOENT\") throw error }\n    }\n    const before = operation.kind === \"add\" ? undefined : readWhole(path)\n    const data = operation.kind === \"add\" ? Buffer.from(operation.lines.join(\"\\n\") + (operation.lines.length ? \"\\n\" : \"\"))\n      : operation.kind === \"update\" ? applyHunks(before!, operation.hunks) : undefined\n    totalBytes += (before?.length ?? 0) + (data?.length ?? 0)\n    if (totalBytes > MAX_BYTES * 2 || (data?.length ?? 0) > MAX_BYTES) throw new ToolError(\"LIMIT_EXCEEDED\", \"Patch working set exceeds the byte limit\", 413)\n    const operationName = operation.kind === \"update\" && target !== path ? \"move\" : operation.kind\n    const change: ApplyPatchOutput[\"changes\"][number] = {operation: operationName, path: target, ...(target === path ? {} : {from: path}), bytes: data?.length ?? 0}\n    return {path, target, before, data, change}\n  })\n  if (dryRun) return {directory, applied: false, changes: planned.map(item => item.change)}\n  const completed: ApplyPatchOutput[\"changes\"] = []\n  for (const item of planned) {\n    try {\n      if (item.before !== undefined && digest(readWhole(item.path)) !== digest(item.before)) throw new ToolError(\"CONFLICT\", \"A patch source changed after validation\", 409)\n      if (item.data !== undefined) {\n        if (item.change.operation === \"update\") replaceFile(item.path, item.data, digest(item.before!))\n        else {\n          mkdirSync(dirname(item.target), {recursive: true})\n          writeFileSync(item.target, item.data, {flag: \"wx\", mode: item.before === undefined ? 0o600 : lstatSync(item.path).mode & 0o777})\n        }\n      }\n      if (item.change.operation === \"delete\" || item.change.operation === \"move\") unlinkSync(item.path)\n      completed.push(item.change)\n    } catch (error) {\n      const failure = asToolError(error)\n      throw new ToolError(\"PARTIAL_FAILURE\", \"Patch application stopped; inspect affected paths before retrying\", 500,\n        {completed, current: item.change, cause: failure.code})\n    }\n  }\n  return {directory, applied: true, changes: completed}\n}\n",
  "filesystem/apply-patch/spec/scenario.spec.ts": "import {test} from \"node:test\"\nimport assert from \"node:assert/strict\"\nimport {writeFileSync, readFileSync, mkdirSync, symlinkSync, existsSync, chmodSync, statSync, readdirSync} from \"node:fs\"\nimport {join, parse} from \"node:path\"\nimport {fixture, hasCode} from \"../../shared/spec-fixture.ts\"\nimport {applyPatch} from \"../index.ts\"\n\ntest(\"patch adds, updates, moves and deletes regular files\", () => fixture(directory => {\n  writeFileSync(join(directory, \"old\"), \"before\\n\"); writeFileSync(join(directory, \"delete\"), \"gone\\n\")\n  const patch = \"*** Begin Patch\\n*** Add File: dir/added\\n+hello\\n*** Update File: old\\n*** Move to: moved\\n@@\\n-before\\n+after\\n*** Delete File: delete\\n*** End Patch\\n\"\n  const result = applyPatch({directory, patch})\n  assert.equal(result.applied, true)\n  assert.equal(result.directory, directory)\n  assert.deepEqual(result.changes.map(change => change.operation), [\"add\", \"move\", \"delete\"])\n  assert.equal(readFileSync(join(directory, \"moved\"), \"utf8\"), \"after\\n\")\n  assert.equal(readFileSync(join(directory, \"dir/added\"), \"utf8\"), \"hello\\n\")\n  assert.equal(existsSync(join(directory, \"old\")), false)\n  assert.equal(existsSync(join(directory, \"delete\")), false)\n}))\ntest(\"patch dryRun performs no writes or parent creation\", () => fixture(directory => {\n  const result = applyPatch({directory, dryRun: true, patch: \"*** Begin Patch\\n*** Add File: new/file\\n+x\\n*** End Patch\"})\n  assert.equal(result.applied, false)\n  assert.equal(existsSync(join(directory, \"new\")), false)\n}))\ntest(\"patch preflights all hunks before writing any file\", () => fixture(directory => {\n  writeFileSync(join(directory, \"existing\"), \"actual\\n\")\n  const patch = \"*** Begin Patch\\n*** Add File: new/file\\n+x\\n*** Update File: existing\\n@@\\n-wrong\\n+bad\\n*** End Patch\"\n  assert.throws(() => applyPatch({directory, patch}), hasCode(\"PATCH_REJECTED\"))\n  assert.equal(existsSync(join(directory, \"new\")), false)\n  assert.equal(readFileSync(join(directory, \"existing\"), \"utf8\"), \"actual\\n\")\n}))\ntest(\"patch refuses ambiguous contexts and duplicate paths\", () => fixture(directory => {\n  writeFileSync(join(directory, \"file\"), \"x\\nx\\n\")\n  assert.throws(() => applyPatch({directory, patch: \"*** Begin Patch\\n*** Update File: file\\n@@\\n-x\\n+y\\n*** End Patch\"}), hasCode(\"PATCH_REJECTED\"))\n  assert.throws(() => applyPatch({directory, patch: \"*** Begin Patch\\n*** Add File: new\\n+x\\n*** Add File: new\\n+y\\n*** End Patch\"}), hasCode(\"PATCH_REJECTED\"))\n  assert.equal(existsSync(join(directory, \"new\")), false)\n}))\ntest(\"patch preserves CRLF and a missing final newline\", () => fixture(directory => {\n  for (const [name, before, after] of [[\"crlf\", \"before\\r\\n\", \"after\\r\\n\"], [\"plain\", \"before\", \"after\"]]) {\n    writeFileSync(join(directory, name!), before!)\n    applyPatch({directory, patch: `*** Begin Patch\\n*** Update File: ${name}\\n@@\\n-before\\n+after\\n*** End Patch`})\n    assert.equal(readFileSync(join(directory, name!), \"utf8\"), after)\n  }\n}))\ntest(\"patch End of File anchors the replacement\", () => fixture(directory => {\n  writeFileSync(join(directory, \"file\"), \"x\\nx\\n\")\n  applyPatch({directory, patch: \"*** Begin Patch\\n*** Update File: file\\n@@\\n-x\\n+y\\n*** End of File\\n*** End Patch\"})\n  assert.equal(readFileSync(join(directory, \"file\"), \"utf8\"), \"x\\ny\\n\")\n}))\ntest(\"patch rejects traversal before changing a valid earlier file\", () => fixture(directory => {\n  assert.throws(() => applyPatch({directory, patch: \"*** Begin Patch\\n*** Add File: good\\n+x\\n*** Add File: ../outside\\n+y\\n*** End Patch\"}), hasCode(\"PATH_NOT_ALLOWED\"))\n  assert.equal(existsSync(join(directory, \"good\")), false)\n}))\ntest(\"patch rejects invalid UTF-8 input files\", () => fixture(directory => {\n  writeFileSync(join(directory, \"binary\"), Buffer.from([255]))\n  assert.throws(() => applyPatch({directory, patch: \"*** Begin Patch\\n*** Update File: binary\\n@@\\n-a\\n+b\\n*** End Patch\"}), hasCode(\"PATCH_REJECTED\"))\n}))\ntest(\"patch rejects a symlink escape before any write\", () => fixture(directory => fixture(outside => {\n  symlinkSync(outside, join(directory, \"alias\"))\n  assert.throws(() => applyPatch({directory, patch: \"*** Begin Patch\\n*** Add File: good\\n+x\\n*** Add File: alias/bad\\n+y\\n*** End Patch\"}), hasCode(\"PATH_NOT_ALLOWED\"))\n  assert.equal(existsSync(join(directory, \"good\")), false)\n  assert.equal(existsSync(join(outside, \"bad\")), false)\n})))\ntest(\"patch reports completed and current operations after an I/O failure\", () => fixture(directory => {\n  // Existing planner semantics: parent/child conflicts may reach the I/O phase.\n  let failure: unknown\n  try { applyPatch({directory, patch: \"*** Begin Patch\\n*** Add File: a\\n+x\\n*** Add File: a/b\\n+y\\n*** End Patch\"}) } catch (error) { failure = error }\n  assert.ok(hasCode(\"PARTIAL_FAILURE\")(failure))\n  const details = (failure as {details: {completed: {path: string}[]; current: {path: string}}}).details\n  assert.equal(details.completed.length, 1)\n  assert.equal(details.completed[0]?.path, join(directory, \"a\"))\n  assert.equal(details.current.path, join(directory, \"a/b\"))\n  assert.equal(readFileSync(join(directory, \"a\"), \"utf8\"), \"x\\n\")\n}))\n",
  "filesystem/apply-patch/src/parse.ts": "import {ToolError} from \"../../../shared/errors.ts\"\n\nexport interface Hunk {old: string[]; next: string[]; end: boolean; anchor?: string}\nexport type Operation = {kind: \"add\"; path: string; lines: string[]} | {kind: \"delete\"; path: string} | {kind: \"update\"; path: string; to?: string; hunks: Hunk[]}\n\nexport function parsePatch(patch: string): Operation[] {\n  const lines = patch.replaceAll(\"\\r\\n\", \"\\n\").split(\"\\n\")\n  if (lines.at(-1) === \"\") lines.pop()\n  if (lines[0] !== \"*** Begin Patch\" || lines.at(-1) !== \"*** End Patch\") throw new ToolError(\"PATCH_REJECTED\", \"Patch must have Begin Patch and End Patch markers\", 409)\n  const operations: Operation[] = []\n  let i = 1\n  const marker = (line: string): boolean => /^\\*\\*\\* (?:Add|Delete|Update) File: /.test(line)\n  while (i < lines.length - 1) {\n    const header = lines[i++]!\n    if (header.startsWith(\"*** Add File: \")) {\n      const added: string[] = []\n      while (i < lines.length - 1 && !marker(lines[i]!)) {\n        const line = lines[i++]!\n        if (!line.startsWith(\"+\")) throw new ToolError(\"PATCH_REJECTED\", \"Added lines must start with +\", 409)\n        added.push(line.slice(1))\n      }\n      operations.push({kind: \"add\", path: header.slice(14), lines: added})\n    } else if (header.startsWith(\"*** Delete File: \")) {\n      operations.push({kind: \"delete\", path: header.slice(17)})\n    } else if (header.startsWith(\"*** Update File: \")) {\n      const path = header.slice(17)\n      let to: string | undefined\n      if (lines[i]?.startsWith(\"*** Move to: \")) to = lines[i++]!.slice(13)\n      const hunks: Hunk[] = []\n      let hunk: Hunk | undefined\n      while (i < lines.length - 1 && !marker(lines[i]!)) {\n        const line = lines[i++]!\n        if (line === \"@@\" || line.startsWith(\"@@ \")) {\n          hunk = {old: [], next: [], end: false, ...(line === \"@@\" ? {} : {anchor: line.slice(3)})}\n          hunks.push(hunk)\n        } else if (line === \"*** End of File\" && hunk !== undefined) {\n          hunk.end = true\n        } else {\n          if (hunk === undefined || hunk.end || ![\" \", \"+\", \"-\"].includes(line[0]!)) throw new ToolError(\"PATCH_REJECTED\", \"Invalid hunk; use @@ followed by context, + or - lines\", 409)\n          if (line[0] !== \"+\") hunk.old.push(line.slice(1))\n          if (line[0] !== \"-\") hunk.next.push(line.slice(1))\n        }\n      }\n      if (hunks.length === 0 && to === undefined) throw new ToolError(\"PATCH_REJECTED\", \"Update has no hunks\", 409)\n      if (hunks.some(h => h.old.length === 0 && h.next.length === 0)) throw new ToolError(\"PATCH_REJECTED\", \"Empty hunks are not allowed\", 409)\n      operations.push({kind: \"update\", path, to, hunks})\n    } else throw new ToolError(\"PATCH_REJECTED\", \"Unknown patch operation\", 409)\n    if (operations.length > 50) throw new ToolError(\"LIMIT_EXCEEDED\", \"A patch may affect at most 50 files\", 413)\n  }\n  if (operations.length === 0) throw new ToolError(\"PATCH_REJECTED\", \"Patch has no operations\", 409)\n  return operations\n}\n\nexport function applyHunks(data: Buffer, hunks: Hunk[]): Buffer {\n  let before: string\n  try { before = new TextDecoder(\"utf-8\", {fatal: true}).decode(data) } catch { throw new ToolError(\"PATCH_REJECTED\", \"Patches only support UTF-8 text\", 409) }\n  const eol = before.includes(\"\\r\\n\") ? \"\\r\\n\" : \"\\n\"\n  const normalized = before.replaceAll(\"\\r\\n\", \"\\n\")\n  if (normalized.includes(\"\\r\") || (eol === \"\\r\\n\" && before.replaceAll(\"\\r\\n\", \"\").includes(\"\\n\"))) throw new ToolError(\"PATCH_REJECTED\", \"Mixed line endings are not supported\", 409)\n  const trailing = normalized.endsWith(\"\\n\")\n  const lines = normalized === \"\" ? [] : normalized.split(\"\\n\")\n  if (trailing) lines.pop()\n  let cursor = 0\n  for (const hunk of hunks) {\n    if (hunk.anchor !== undefined) {\n      const anchor = lines.indexOf(hunk.anchor, cursor)\n      if (anchor < 0 || lines.indexOf(hunk.anchor, anchor + 1) >= 0) throw new ToolError(\"PATCH_REJECTED\", \"Hunk anchor is absent or ambiguous\", 409)\n      cursor = anchor + 1\n    }\n    let position = -1\n    for (let i = cursor; i <= lines.length - hunk.old.length; i++) {\n      if (hunk.end && i + hunk.old.length !== lines.length) continue\n      if (!hunk.old.every((line, j) => lines[i + j] === line)) continue\n      if (position !== -1 && hunk.old.length !== 0) throw new ToolError(\"PATCH_REJECTED\", \"Hunk matches more than once; provide more context\", 409)\n      position = i\n      if (hunk.old.length === 0) break\n    }\n    if (position < 0) throw new ToolError(\"PATCH_REJECTED\", \"Hunk does not match the current file\", 409)\n    lines.splice(position, hunk.old.length, ...hunk.next)\n    cursor = position + hunk.next.length\n  }\n  return Buffer.from(lines.join(eol) + (lines.length > 0 && (trailing || before === \"\") ? eol : \"\"), \"utf8\")\n}\n",
  "filesystem/apply-patch/src/paths.ts": "import {isAbsolute, join} from \"node:path\"\nimport {ToolError} from \"../../../shared/errors.ts\"\nimport {text} from \"../../../shared/validation.ts\"\nimport {resolvePath, within} from \"../../shared/paths.ts\"\n\n/** A patch supplies relative filenames, not a session or a registered workspace. */\nexport function patchPath(directory: string, value: unknown, missing = false): string {\n  const name = text(value, \"patch path\")\n  const parts = name.split(\"/\").filter(part => part !== \"\" && part !== \".\")\n  if (isAbsolute(name) || name.includes(\"\\\\\") || name.includes(\"\\0\") || /^[a-zA-Z]:/.test(name) || parts.length === 0 || parts.includes(\"..\")) {\n    throw new ToolError(\"PATH_NOT_ALLOWED\", \"Patch filenames must stay relative to directory\", 403)\n  }\n  const path = resolvePath(join(directory, ...parts), {missing, mutable: true})\n  if (path === directory || !within(directory, path)) throw new ToolError(\"PATH_NOT_ALLOWED\", \"A patch filename escapes directory\", 403)\n  return path\n}\n",
  "filesystem/create/contract/input.ts": "/** Standalone tool input. Authorization belongs to the calling host. */\nexport interface CreateFileInput {\n  /** Absolute path of a new file. Existing destinations are never replaced. */\n  path: string\n  content: string\n  encoding?: \"utf8\" | \"base64\"\n  /** Default false. I/O failure may leave newly created parents. */\n  createParents?: boolean\n}\n",
  "filesystem/create/contract/output.ts": "/** Filesystem paths in results are absolute; no workspace identity is returned. */\nexport interface CreateFileOutput {\n  path: string\n  bytes: number\n  contentHash: string\n}\n",
  "filesystem/create/index.ts": "/**\n * Создаёт новый файл, не перезаписывая существующий. Создание родителей только по явному флагу.\n * @packageDocumentation\n */\nimport {mkdirSync, writeFileSync} from \"node:fs\"\nimport {dirname} from \"node:path\"\nimport {object, text, encoding, boolean} from \"../../shared/validation.ts\"\nimport {resolvePath} from \"../shared/paths.ts\"\nimport {decode, digest} from \"../shared/files.ts\"\nimport type {CreateFileInput} from \"./contract/input.ts\"\nimport type {CreateFileOutput} from \"./contract/output.ts\"\nexport type {CreateFileInput} from \"./contract/input.ts\"\nexport type {CreateFileOutput} from \"./contract/output.ts\"\n\nexport function createFile(input: CreateFileInput): CreateFileOutput {\n  object(input, [\"path\", \"content\", \"encoding\", \"createParents\"])\n  const data = decode(text(input.content, \"content\", true), encoding(input.encoding))\n  const parents = boolean(input.createParents, false, \"createParents\")\n  const path = resolvePath(input.path, {missing: true, mutable: true})\n  if (parents) mkdirSync(dirname(path), {recursive: true})\n  writeFileSync(path, data, {flag: \"wx\", mode: 0o600})\n  return {path, bytes: data.length, contentHash: digest(data)}\n}\n",
  "filesystem/create/spec/scenario.spec.ts": "import {test} from \"node:test\"\nimport assert from \"node:assert/strict\"\nimport {writeFileSync, readFileSync, mkdirSync, symlinkSync, existsSync, chmodSync, statSync, readdirSync} from \"node:fs\"\nimport {join, parse} from \"node:path\"\nimport {fixture, hasCode} from \"../../shared/spec-fixture.ts\"\nimport {createFile} from \"../index.ts\"\n\ntest(\"create writes a new file and rejects a duplicate\", () => fixture(directory => {\n  const path = join(directory, \"file\")\n  createFile({path, content: \"hello\"})\n  assert.throws(() => createFile({path, content: \"bad\"}), hasCode(\"EEXIST\"))\n  assert.equal(readFileSync(path, \"utf8\"), \"hello\")\n}))\ntest(\"create requires explicit parent creation\", () => fixture(directory => {\n  const path = join(directory, \"a/file\")\n  assert.throws(() => createFile({path, content: \"\"}), hasCode(\"ENOENT\"))\n  assert.equal(existsSync(join(directory, \"a\")), false)\n  createFile({path, content: \"\", createParents: true})\n  assert.equal(existsSync(path), true)\n}))\ntest(\"create validates input and byte budget before creating parents\", () => fixture(directory => {\n  const path = join(directory, \"a/file\")\n  assert.throws(() => createFile({path, content: \"!\", encoding: \"base64\", createParents: true}), hasCode(\"INVALID_INPUT\"))\n  assert.throws(() => createFile({path, content: \"x\".repeat(8388609), createParents: true}), hasCode(\"LIMIT_EXCEEDED\"))\n  assert.equal(existsSync(join(directory, \"a\")), false)\n}))\ntest(\"create rejects a dangling final or parent symlink\", () => fixture(directory => {\n  symlinkSync(\"missing\", join(directory, \"link\"))\n  assert.throws(() => createFile({path: join(directory, \"link\"), content: \"x\"}), hasCode(\"PATH_NOT_ALLOWED\"))\n  assert.throws(() => createFile({path: join(directory, \"link/file\"), content: \"x\", createParents: true}), hasCode(\"PATH_NOT_ALLOWED\"))\n  assert.equal(existsSync(join(directory, \"missing\")), false)\n}))\n",
  "filesystem/list/contract/input.ts": "/** Standalone tool input. Authorization belongs to the calling host. */\nexport interface ListFilesInput {\n  /** Absolute directory path; never inferred from process.cwd(). */\n  path: string\n  recursive?: boolean\n  /** Default 3; range 1..10. */\n  maxDepth?: number\n  /** Default 1000; range 1..5000. Truncation is not pagination. */\n  maxEntries?: number\n}\n",
  "filesystem/list/contract/output.ts": "import type {FileEntry} from \"../../shared/types.ts\"\n\n/** Filesystem paths in results are absolute; no workspace identity is returned. */\nexport interface ListFilesOutput {\n  path: string\n  entries: FileEntry[]\n  truncated: boolean\n  depthLimited: boolean\n}\n",
  "filesystem/list/index.ts": "/**\n * Строит ограниченный инвентарь обычного каталога. Не скрывает .git и не обходит дочерние symlink.\n * @packageDocumentation\n */\nimport {opendirSync, lstatSync} from \"node:fs\"\nimport {join} from \"node:path\"\nimport {object, integer, boolean} from \"../../shared/validation.ts\"\nimport {ToolError} from \"../../shared/errors.ts\"\nimport {resolvePath} from \"../shared/paths.ts\"\nimport {metadata} from \"../shared/files.ts\"\nimport type {ListFilesInput} from \"./contract/input.ts\"\nimport type {ListFilesOutput} from \"./contract/output.ts\"\nexport type {ListFilesInput} from \"./contract/input.ts\"\nexport type {ListFilesOutput} from \"./contract/output.ts\"\n\nexport function listFiles(input: ListFilesInput): ListFilesOutput {\n  object(input, [\"path\", \"recursive\", \"maxDepth\", \"maxEntries\"])\n  const start = resolvePath(input.path)\n  const recursive = boolean(input.recursive, false, \"recursive\")\n  const maxDepth = integer(input.maxDepth, 3, 1, 10, \"maxDepth\")\n  const maxEntries = integer(input.maxEntries, 1000, 1, 5000, \"maxEntries\")\n  if (!lstatSync(start).isDirectory()) throw new ToolError(\"INVALID_PATH_TYPE\", \"Path must be a directory\")\n  const entries: ListFilesOutput[\"entries\"] = []\n  let truncated = false\n  let depthLimited = false\n  const visit = (directory: string, depth: number): void => {\n    const handle = opendirSync(directory)\n    try {\n      let child\n      while ((child = handle.readSync()) !== null) {\n        if (entries.length === maxEntries) { truncated = true; return }\n        const path = join(directory, child.name)\n        const entry = metadata(path)\n        entries.push(entry)\n        if (recursive && entry.type === \"directory\") {\n          if (depth < maxDepth) visit(path, depth + 1)\n          else depthLimited = true\n          if (truncated) return\n        }\n      }\n    } finally { handle.closeSync() }\n  }\n  visit(start, 1)\n  entries.sort((a, b) => a.path.localeCompare(b.path))\n  return {path: start, entries, truncated: truncated || depthLimited, depthLimited}\n}\n",
  "filesystem/list/spec/scenario.spec.ts": "import {test} from \"node:test\"\nimport assert from \"node:assert/strict\"\nimport {writeFileSync, readFileSync, mkdirSync, symlinkSync, existsSync, chmodSync, statSync, readdirSync} from \"node:fs\"\nimport {join, parse} from \"node:path\"\nimport {fixture, hasCode} from \"../../shared/spec-fixture.ts\"\nimport {listFiles} from \"../index.ts\"\n\ntest(\"list includes ordinary .git entries but does not traverse child symlinks\", () => fixture(directory => {\n  mkdirSync(join(directory, \".git\")); writeFileSync(join(directory, \".git/config\"), \"data\")\n  mkdirSync(join(directory, \"dir\")); writeFileSync(join(directory, \"dir/file\"), \"ok\")\n  symlinkSync(\"dir\", join(directory, \"link\"))\n  const paths = listFiles({path: directory, recursive: true}).entries.map(entry => entry.path)\n  assert.ok(paths.includes(join(directory, \"dir/file\")))\n  assert.ok(paths.includes(join(directory, \".git/config\")))\n  assert.ok(paths.includes(join(directory, \"link\")))\n  assert.ok(!paths.some(path => path.startsWith(join(directory, \"link\") + \"/\")))\n}))\ntest(\"list reports entry truncation\", () => fixture(directory => {\n  for (let i = 0; i < 5; i++) writeFileSync(join(directory, `${i}`), \"\")\n  const result = listFiles({path: directory, maxEntries: 2})\n  assert.equal(result.entries.length, 2)\n  assert.equal(result.truncated, true)\n}))\ntest(\"list reports depth-limited inventories\", () => fixture(directory => {\n  mkdirSync(join(directory, \"a/b\"), {recursive: true})\n  writeFileSync(join(directory, \"a/b/file\"), \"\")\n  const result = listFiles({path: directory, recursive: true, maxDepth: 1})\n  assert.equal(result.depthLimited, true)\n  assert.equal(result.truncated, true)\n}))\ntest(\"list reports an empty directory as complete and requires an explicit path\", () => fixture(directory => {\n  const result = listFiles({path: directory})\n  assert.deepEqual(result.entries, [])\n  assert.equal(result.truncated, false)\n  assert.throws(() => listFiles({} as never), hasCode(\"INVALID_INPUT\"))\n}))\n",
  "filesystem/mkdir/contract/input.ts": "/** Standalone tool input. Authorization belongs to the calling host. */\nexport interface MakeDirectoryInput {\n  /** Absolute directory path. */\n  path: string\n  /** Default false. With true, repetition returns created:false. */\n  recursive?: boolean\n}\n",
  "filesystem/mkdir/contract/output.ts": "/** Filesystem paths in results are absolute; no workspace identity is returned. */\nexport interface MakeDirectoryOutput {\n  path: string\n  created: boolean\n}\n",
  "filesystem/mkdir/index.ts": "/**\n * Создаёт каталог по абсолютному пути. recursive:true допускает повтор с created:false.\n * @packageDocumentation\n */\nimport {mkdirSync, lstatSync} from \"node:fs\"\nimport {object, boolean} from \"../../shared/validation.ts\"\nimport {resolvePath} from \"../shared/paths.ts\"\nimport type {MakeDirectoryInput} from \"./contract/input.ts\"\nimport type {MakeDirectoryOutput} from \"./contract/output.ts\"\nexport type {MakeDirectoryInput} from \"./contract/input.ts\"\nexport type {MakeDirectoryOutput} from \"./contract/output.ts\"\n\nexport function makeDirectory(input: MakeDirectoryInput): MakeDirectoryOutput {\n  object(input, [\"path\", \"recursive\"])\n  const recursive = boolean(input.recursive, false, \"recursive\")\n  const path = resolvePath(input.path, {missing: true, mutable: true})\n  let existed = false\n  try { existed = lstatSync(path).isDirectory() } catch (error) { if ((error as NodeJS.ErrnoException).code !== \"ENOENT\") throw error }\n  mkdirSync(path, {recursive})\n  return {path, created: !existed}\n}\n",
  "filesystem/mkdir/spec/scenario.spec.ts": "import {test} from \"node:test\"\nimport assert from \"node:assert/strict\"\nimport {writeFileSync, readFileSync, mkdirSync, symlinkSync, existsSync, chmodSync, statSync, readdirSync} from \"node:fs\"\nimport {join, parse} from \"node:path\"\nimport {fixture, hasCode} from \"../../shared/spec-fixture.ts\"\nimport {makeDirectory} from \"../index.ts\"\n\ntest(\"mkdir recursive mode reports creation and idempotent repetition\", () => fixture(directory => {\n  const path = join(directory, \"a/b\")\n  assert.equal(makeDirectory({path, recursive: true}).created, true)\n  assert.equal(makeDirectory({path, recursive: true}).created, false)\n  assert.equal(existsSync(path), true)\n}))\ntest(\"mkdir refuses filesystem root and invalid recursive flag\", () => fixture(directory => {\n  assert.throws(() => makeDirectory({path: parse(directory).root}), hasCode(\"PATH_NOT_ALLOWED\"))\n  assert.throws(() => makeDirectory({path: join(directory, \"a\"), recursive: \"true\"} as never), hasCode(\"INVALID_INPUT\"))\n}))\n",
  "filesystem/package.json": "{\n  \"name\": \"@ai/filesystem\",\n  \"label\": \"Filesystem\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"exports\": {\n    \"./stat\": \"./stat/index.ts\",\n    \"./read\": \"./read/index.ts\",\n    \"./read-many\": \"./read-many/index.ts\",\n    \"./list\": \"./list/index.ts\",\n    \"./write\": \"./write/index.ts\",\n    \"./create\": \"./create/index.ts\",\n    \"./mkdir\": \"./mkdir/index.ts\",\n    \"./remove\": \"./remove/index.ts\",\n    \"./rename\": \"./rename/index.ts\",\n    \"./apply-patch\": \"./apply-patch/index.ts\"\n  }\n}\n",
  "filesystem/read/contract/input.ts": "/** Standalone tool input. Authorization belongs to the calling host. */\nexport interface ReadFileInput {\n  /** Absolute host path. Existing parent symlinks are canonicalized; a final symlink is rejected. */\n  path: string\n  /** Byte offset, default 0. */\n  offset?: number\n  /** Default 65536; maximum 8388608. */\n  maxBytes?: number\n  /** Use base64 for binary data or byte ranges splitting UTF-8 characters. */\n  encoding?: \"utf8\" | \"base64\"\n}\n",
  "filesystem/read/contract/output.ts": "/** Filesystem paths in results are absolute; no workspace identity is returned. */\nexport interface ReadFileOutput {\n  path: string\n  content: string\n  encoding: \"utf8\" | \"base64\"\n  offset: number\n  bytesRead: number\n  size: number\n  truncated: boolean\n  /** Only present as a hash after reading a whole file; otherwise null. */\n  contentHash: string | null\n}\n",
  "filesystem/read/index.ts": "/**\n * Читает ограниченный диапазон байтов по абсолютному пути. Без регистрации и контекста.\n * @packageDocumentation\n */\nimport {object, integer, encoding} from \"../../shared/validation.ts\"\nimport {resolvePath} from \"../shared/paths.ts\"\nimport {readChunk, digest, MAX_BYTES} from \"../shared/files.ts\"\nimport type {ReadFileInput} from \"./contract/input.ts\"\nimport type {ReadFileOutput} from \"./contract/output.ts\"\nexport type {ReadFileInput} from \"./contract/input.ts\"\nexport type {ReadFileOutput} from \"./contract/output.ts\"\n\nexport function readFile(input: ReadFileInput): ReadFileOutput {\n  object(input, [\"path\", \"offset\", \"maxBytes\", \"encoding\"])\n  const offset = integer(input.offset, 0, 0, Number.MAX_SAFE_INTEGER, \"offset\")\n  const maxBytes = integer(input.maxBytes, 65536, 1, MAX_BYTES, \"maxBytes\")\n  const format = encoding(input.encoding)\n  const path = resolvePath(input.path)\n  const {data, size} = readChunk(path, offset, maxBytes)\n  return {path, content: data.toString(format), encoding: format,\n    offset, bytesRead: data.length, size, truncated: offset + data.length < size,\n    contentHash: offset === 0 && data.length === size ? digest(data) : null}\n}\n",
  "filesystem/read/spec/scenario.spec.ts": "import {test} from \"node:test\"\nimport assert from \"node:assert/strict\"\nimport {writeFileSync, readFileSync, mkdirSync, symlinkSync, existsSync, chmodSync, statSync, readdirSync} from \"node:fs\"\nimport {join, parse} from \"node:path\"\nimport {fixture, hasCode} from \"../../shared/spec-fixture.ts\"\nimport {readFile} from \"../index.ts\"\n\ntest(\"read needs only an absolute path and reports a complete file/hash\", () => fixture(directory => {\n  const path = join(directory, \"hello.txt\")\n  writeFileSync(path, \"hello\")\n  const result = readFile({path})\n  assert.equal(result.path, path)\n  assert.equal(result.content, \"hello\")\n  assert.equal(result.bytesRead, 5)\n  assert.equal(result.truncated, false)\n  assert.match(result.contentHash!, /^[a-f0-9]{64}$/)\n  assert.equal(\"root\" in result, false)\n}))\ntest(\"read reports byte-range truncation without a whole-file hash\", () => fixture(directory => {\n  const path = join(directory, \"file\")\n  writeFileSync(path, \"abcdef\")\n  const result = readFile({path, offset: 1, maxBytes: 2})\n  assert.equal(result.content, \"bc\")\n  assert.equal(result.bytesRead, 2)\n  assert.equal(result.contentHash, null)\n  assert.equal(result.truncated, true)\n}))\ntest(\"read handles empty files and offsets beyond EOF\", () => fixture(directory => {\n  const path = join(directory, \"empty\")\n  writeFileSync(path, \"\")\n  assert.equal(readFile({path}).bytesRead, 0)\n  const result = readFile({path, offset: 100})\n  assert.equal(result.truncated, false)\n  assert.equal(result.contentHash, null)\n}))\ntest(\"read base64 preserves binary and split UTF-8 bytes\", () => fixture(directory => {\n  const path = join(directory, \"binary\")\n  const bytes = Buffer.from([0, 255, 1, 128])\n  writeFileSync(path, bytes)\n  const result = readFile({path, encoding: \"base64\", offset: 1, maxBytes: 2})\n  assert.deepEqual(Buffer.from(result.content, \"base64\"), bytes.subarray(1, 3))\n}))\nfor (const path of [\"relative\", \"../secret\", \"\", \"~/.config\", \"bad\\0name\"]) {\n  test(`read never infers a directory for ${JSON.stringify(path)}`, () => {\n    assert.throws(() => readFile({path}), hasCode(path === \"\" ? \"INVALID_INPUT\" : \"PATH_NOT_ALLOWED\"))\n  })\n}\ntest(\"read allows an ordinary .git-named file and normalizes an absolute path\", () => fixture(directory => {\n  mkdirSync(join(directory, \".git\"))\n  writeFileSync(join(directory, \".git/config\"), \"ordinary data\")\n  assert.equal(readFile({path: join(directory, \".git/config\")}).content, \"ordinary data\")\n  assert.equal(readFile({path: `${directory}/unused/../.git/config`}).content, \"ordinary data\")\n}))\ntest(\"read rejects a final symlink but canonicalizes existing parent aliases\", () => fixture(directory => {\n  mkdirSync(join(directory, \"real\"))\n  writeFileSync(join(directory, \"real/file\"), \"data\")\n  symlinkSync(\"real/file\", join(directory, \"link\"))\n  symlinkSync(\"real\", join(directory, \"alias\"))\n  assert.throws(() => readFile({path: join(directory, \"link\")}), hasCode(\"PATH_NOT_ALLOWED\"))\n  const result = readFile({path: join(directory, \"alias/file\")})\n  assert.equal(result.content, \"data\")\n  assert.equal(result.path, join(directory, \"real/file\"))\n}))\ntest(\"read validates numbers, encoding, input shape, legacy root and target type\", () => fixture(directory => {\n  const path = join(directory, \"file\")\n  writeFileSync(path, \"data\")\n  for (const extra of [{maxBytes: 0}, {maxBytes: 8388609}, {offset: -1}, {offset: 1.5}, {encoding: \"latin1\"}, {root: \"repo\"}]) {\n    assert.throws(() => readFile({path, ...extra} as never), hasCode(\"INVALID_INPUT\"))\n  }\n  assert.throws(() => readFile(null as never), hasCode(\"INVALID_INPUT\"))\n  assert.throws(() => readFile({path: directory}), hasCode(\"INVALID_PATH_TYPE\"))\n  assert.throws(() => readFile({path: `${directory}/bad\\0name`}), hasCode(\"PATH_NOT_ALLOWED\"))\n  assert.throws(() => readFile({path: `${directory}/${\"x\".repeat(4096)}`}), hasCode(\"PATH_NOT_ALLOWED\"))\n}))\n",
  "filesystem/read-many/contract/input.ts": "/** Standalone tool input. Authorization belongs to the calling host. */\nexport interface ReadFilesInput {\n  /** 1..50 absolute paths; files may belong to different directories. */\n  paths: string[]\n  encoding?: \"utf8\" | \"base64\"\n  /** Default 65536; maximum 8388608. */\n  maxBytesPerFile?: number\n  /** Default 2097152; maximum 8388608. */\n  maxTotalBytes?: number\n}\n",
  "filesystem/read-many/contract/output.ts": "import type {ReadFileOutput} from \"../../read/contract/output.ts\"\n\n/** Filesystem paths in results are absolute; no workspace identity is returned. */\nexport interface ReadFilesOutput {\n  files: ({path: string; result: ReadFileOutput} | {path: string; error: {code: string; message: string}})[]\n  bytesRead: number\n  remainingBytes: number\n  truncated: boolean\n}\n",
  "filesystem/read-many/index.ts": "/**\n * Читает до 50 абсолютных путей с общим бюджетом байтов и отдельными результатами ошибок.\n * @packageDocumentation\n */\nimport {object, integer, encoding, text} from \"../../shared/validation.ts\"\nimport {ToolError, asToolError} from \"../../shared/errors.ts\"\nimport {MAX_BYTES} from \"../shared/files.ts\"\nimport {readFile} from \"../read/index.ts\"\nimport type {ReadFilesInput} from \"./contract/input.ts\"\nimport type {ReadFilesOutput} from \"./contract/output.ts\"\nexport type {ReadFilesInput} from \"./contract/input.ts\"\nexport type {ReadFilesOutput} from \"./contract/output.ts\"\n\nexport function readFiles(input: ReadFilesInput): ReadFilesOutput {\n  object(input, [\"paths\", \"encoding\", \"maxBytesPerFile\", \"maxTotalBytes\"])\n  if (!Array.isArray(input.paths) || input.paths.length === 0 || input.paths.length > 50) throw new ToolError(\"INVALID_INPUT\", \"paths must contain 1 to 50 strings\")\n  input.paths.forEach(path => text(path, \"path\"))\n  const format = encoding(input.encoding)\n  const perFile = integer(input.maxBytesPerFile, 65536, 1, MAX_BYTES, \"maxBytesPerFile\")\n  const total = integer(input.maxTotalBytes, 2 * 1024 * 1024, 1, MAX_BYTES, \"maxTotalBytes\")\n  let remaining = total\n  let truncated = false\n  const files = input.paths.map(path => {\n    try {\n      if (remaining === 0) throw new ToolError(\"LIMIT_EXCEEDED\", \"The shared read budget is exhausted\", 413)\n      const result = readFile({path, encoding: format, maxBytes: Math.min(perFile, remaining)})\n      remaining -= result.bytesRead\n      truncated ||= result.truncated\n      return {path, result}\n    } catch (error) {\n      const failure = asToolError(error)\n      truncated = true\n      return {path, error: {code: failure.code, message: failure.message}}\n    }\n  })\n  return {files, bytesRead: total - remaining, remainingBytes: remaining, truncated}\n}\n",
  "filesystem/read-many/spec/scenario.spec.ts": "import {test} from \"node:test\"\nimport assert from \"node:assert/strict\"\nimport {writeFileSync, readFileSync, mkdirSync, symlinkSync, existsSync, chmodSync, statSync, readdirSync} from \"node:fs\"\nimport {join, parse} from \"node:path\"\nimport {fixture, hasCode} from \"../../shared/spec-fixture.ts\"\nimport {readFiles} from \"../index.ts\"\n\ntest(\"read-many enforces its shared byte budget\", () => fixture(directory => {\n  const a = join(directory, \"a\"), b = join(directory, \"b\")\n  writeFileSync(a, \"1234\"); writeFileSync(b, \"5678\")\n  const result = readFiles({paths: [a, b, a], maxTotalBytes: 5})\n  assert.equal(result.bytesRead, 5)\n  assert.equal(result.remainingBytes, 0)\n  assert.equal(result.truncated, true)\n  assert.ok(\"error\" in result.files[2]!)\n}))\ntest(\"read-many preserves per-file errors and successes\", () => fixture(directory => {\n  const path = join(directory, \"ok\")\n  writeFileSync(path, \"yes\")\n  const result = readFiles({paths: [join(directory, \"missing\"), path]})\n  assert.ok(\"error\" in result.files[0]!)\n  assert.ok(\"result\" in result.files[1]!)\n  assert.equal(result.bytesRead, 3)\n}))\ntest(\"read-many works across unrelated directories without a context\", () => fixture(a => fixture(b => {\n  writeFileSync(join(a, \"a\"), \"one\"); writeFileSync(join(b, \"b\"), \"two\")\n  const result = readFiles({paths: [join(a, \"a\"), join(b, \"b\")]})\n  assert.equal(result.bytesRead, 6)\n  assert.equal(result.truncated, false)\n  assert.equal(\"root\" in result, false)\n})))\ntest(\"read-many rejects invalid batches before reading\", () => {\n  for (const paths of [[], Array(51).fill(\"x\"), [1]]) {\n    assert.throws(() => readFiles({paths} as never), hasCode(\"INVALID_INPUT\"))\n  }\n})\n",
  "filesystem/README.md": "# Filesystem\n\nДесять универсальных функций принимают обычные абсолютные пути. Нет roots/open,\ncreateFilesystem, aliases, workspace ID, регистрации или второго аргумента context.\nДиректория не обязана быть Git checkout. Права определяет вызывающий процесс/хост.\n\nПубличные входы: stat, list, read, read-many, write, create, mkdir, remove,\nrename, apply-patch. У каждого — Input/Output в contract/ и сценарии в spec/.\n\nПути не вычисляются из process.cwd(). Существующие родители канонизируются,\nв том числе системные symlink-aliases вроде /tmp на macOS. Конечный symlink\nне разыменовывается: stat описывает ссылку, remove удаляет ссылку, rename\nперемещает ссылку; чтение и запись через конечную ссылку отклоняются.\nlist показывает .git как обычную директорию и не обходит дочерние symlink.\nЭта обработка путей не является авторизацией или защитой от локальных гонок.\n\nread использует диапазон байтов; для двоичных данных и диапазонов внутри UTF-8\nсимвола используйте base64. contentHash есть только у полного чтения.\nread-many принимает до 50 независимых путей, сохраняет ошибки каждого файла\nи ограничивает отдельный файл и общую сумму. Чтение/запись ограничены 8 MiB.\nlist возвращает ограниченный инвентарь; усечение не является пагинацией.\n\nwrite заменяет существующий обычный файл через временный файл и rename,\nсохраняя permission bits. Inode, mtime и свойства старого inode могут измениться.\nexpectedHash отклоняет устаревшее содержимое, но не блокирует другой процесс.\ncreate использует исключительное создание. Родители не создаются неявно,\nкроме явного createParents и добавления файлов через patch.\nremove требует recursive:true для непустого каталога. rename не перезаписывает\nсуществующую цель и может работать между разными директориями. Переход между\nфайловыми системами не превращается в скрытое копирование. Проверка отсутствия\nцели rename не является межпроцессной блокировкой. Корень ФС изменять нельзя.\n\napply-patch принимает directory и patch; пути внутри патча относительные,\nне могут выйти из указанной директории, в том числе через родительский symlink.\nПоддержаны Begin Patch, Add/Update/Delete File, Move to, hunks @@,\nточные anchors @@ text и End of File. Неоднозначные совпадения, fuzzy matching\nи повторные пути отклоняются. Сохраняются CRLF и отсутствие финального newline;\nсмешанные окончания строк отклоняются. dryRun планирует без изменения файлов.\n\nВсе операции планируются до записи, но не все будущие ошибки ФС предсказуемы.\nНапример, создание файла a, затем a/b может завершиться после первой записи.\nОшибка применения даёт PARTIAL_FAILURE с completed, current и cause.\nЭто не многофайловая транзакция; автоматического отката и повторов нет.\n\nЧтения идемпотентны при неизменных данных. Повторы create, remove и rename после\nуспеха могут дать конфликт/NOT_FOUND. mkdir recursive допускает повтор и сообщает\ncreated:false. Повтор write без expectedHash сохраняет байты, но не inode/mtime.\nФайловая запись не запускает debugger, remap, replay или перезапуск приложения.\n",
  "filesystem/remove/contract/input.ts": "/** Standalone tool input. Authorization belongs to the calling host. */\nexport interface RemovePathInput {\n  /** Absolute path. The final symlink is unlinked, not followed. */\n  path: string\n  /** Default false; required to remove a nonempty directory. */\n  recursive?: boolean\n}\n",
  "filesystem/remove/contract/output.ts": "/** Filesystem paths in results are absolute; no workspace identity is returned. */\nexport interface RemovePathOutput {\n  path: string\n  removed: true\n}\n",
  "filesystem/remove/index.ts": "/**\n * Удаляет файл, конечный symlink или каталог. Рекурсия только явно; корень файловой системы защищён.\n * @packageDocumentation\n */\nimport {lstatSync, unlinkSync, rmSync, rmdirSync} from \"node:fs\"\nimport {object, boolean} from \"../../shared/validation.ts\"\nimport {resolvePath} from \"../shared/paths.ts\"\nimport type {RemovePathInput} from \"./contract/input.ts\"\nimport type {RemovePathOutput} from \"./contract/output.ts\"\nexport type {RemovePathInput} from \"./contract/input.ts\"\nexport type {RemovePathOutput} from \"./contract/output.ts\"\n\nexport function removePath(input: RemovePathInput): RemovePathOutput {\n  object(input, [\"path\", \"recursive\"])\n  const recursive = boolean(input.recursive, false, \"recursive\")\n  const path = resolvePath(input.path, {finalSymlink: true, mutable: true})\n  const stat = lstatSync(path)\n  if (stat.isDirectory()) {\n    if (recursive) rmSync(path, {recursive: true, force: false})\n    else rmdirSync(path)\n  } else unlinkSync(path)\n  return {path, removed: true}\n}\n",
  "filesystem/remove/spec/scenario.spec.ts": "import {test} from \"node:test\"\nimport assert from \"node:assert/strict\"\nimport {writeFileSync, readFileSync, mkdirSync, symlinkSync, existsSync, chmodSync, statSync, readdirSync} from \"node:fs\"\nimport {join, parse} from \"node:path\"\nimport {fixture, hasCode} from \"../../shared/spec-fixture.ts\"\nimport {removePath} from \"../index.ts\"\n\ntest(\"remove requires explicit recursion for a nonempty directory\", () => fixture(directory => {\n  const path = join(directory, \"dir\")\n  mkdirSync(path); writeFileSync(join(path, \"file\"), \"x\")\n  assert.throws(() => removePath({path}))\n  assert.equal(existsSync(join(path, \"file\")), true)\n  removePath({path, recursive: true})\n  assert.equal(existsSync(path), false)\n}))\ntest(\"remove unlinks a final symlink without deleting its target\", () => fixture(directory => {\n  writeFileSync(join(directory, \"target\"), \"x\"); symlinkSync(\"target\", join(directory, \"link\"))\n  removePath({path: join(directory, \"link\")})\n  assert.equal(existsSync(join(directory, \"target\")), true)\n}))\ntest(\"remove protects the filesystem root and reports repeated deletion\", () => fixture(directory => {\n  assert.throws(() => removePath({path: parse(directory).root, recursive: true}), hasCode(\"PATH_NOT_ALLOWED\"))\n  const path = join(directory, \"file\"); writeFileSync(path, \"x\")\n  removePath({path})\n  assert.throws(() => removePath({path}), hasCode(\"ENOENT\"))\n}))\n",
  "filesystem/rename/contract/input.ts": "/** Standalone tool input. Authorization belongs to the calling host. */\nexport interface RenamePathInput {\n  /** Absolute source path. */\n  from: string\n  /** Absolute destination. No overwrite or implicit parent creation. */\n  to: string\n}\n",
  "filesystem/rename/contract/output.ts": "/** Filesystem paths in results are absolute; no workspace identity is returned. */\nexport interface RenamePathOutput {\n  from: string\n  to: string\n  renamed: true\n}\n",
  "filesystem/rename/index.ts": "/**\n * Перемещает между абсолютными путями без перезаписи цели. EXDEV не заменяется скрытым копированием.\n * @packageDocumentation\n */\nimport {lstatSync, renameSync} from \"node:fs\"\nimport {object} from \"../../shared/validation.ts\"\nimport {ToolError} from \"../../shared/errors.ts\"\nimport {resolvePath, within} from \"../shared/paths.ts\"\nimport type {RenamePathInput} from \"./contract/input.ts\"\nimport type {RenamePathOutput} from \"./contract/output.ts\"\nexport type {RenamePathInput} from \"./contract/input.ts\"\nexport type {RenamePathOutput} from \"./contract/output.ts\"\n\nexport function renamePath(input: RenamePathInput): RenamePathOutput {\n  object(input, [\"from\", \"to\"])\n  const from = resolvePath(input.from, {finalSymlink: true, mutable: true})\n  const to = resolvePath(input.to, {missing: true, finalSymlink: true, mutable: true})\n  try {\n    lstatSync(to)\n    throw new ToolError(\"CONFLICT\", \"Destination already exists\", 409)\n  } catch (error) { if ((error as NodeJS.ErrnoException).code !== \"ENOENT\") throw error }\n  if (lstatSync(from).isDirectory() && within(from, to)) throw new ToolError(\"INVALID_INPUT\", \"A directory cannot be moved into itself\")\n  renameSync(from, to)\n  return {from, to, renamed: true}\n}\n",
  "filesystem/rename/spec/scenario.spec.ts": "import {test} from \"node:test\"\nimport assert from \"node:assert/strict\"\nimport {writeFileSync, readFileSync, mkdirSync, symlinkSync, existsSync, chmodSync, statSync, readdirSync} from \"node:fs\"\nimport {join, parse} from \"node:path\"\nimport {fixture, hasCode} from \"../../shared/spec-fixture.ts\"\nimport {renamePath} from \"../index.ts\"\n\ntest(\"rename moves a file to a new path\", () => fixture(directory => {\n  const from = join(directory, \"from\"), to = join(directory, \"to\")\n  writeFileSync(from, \"data\"); renamePath({from, to})\n  assert.equal(existsSync(from), false)\n  assert.equal(readFileSync(to, \"utf8\"), \"data\")\n}))\ntest(\"rename moves between unrelated directories without aliases\", () => fixture(a => fixture(b => {\n  const from = join(a, \"file\"), to = join(b, \"file\")\n  writeFileSync(from, \"data\")\n  assert.deepEqual(renamePath({from, to}), {from, to, renamed: true})\n  assert.equal(readFileSync(to, \"utf8\"), \"data\")\n})))\ntest(\"rename does not overwrite an existing target\", () => fixture(directory => {\n  const from = join(directory, \"a\"), to = join(directory, \"b\")\n  writeFileSync(from, \"a\"); writeFileSync(to, \"b\")\n  assert.throws(() => renamePath({from, to}), hasCode(\"CONFLICT\"))\n  assert.equal(readFileSync(to, \"utf8\"), \"b\")\n}))\ntest(\"rename rejects filesystem root and moving a directory into itself\", () => fixture(directory => {\n  const from = join(directory, \"dir\"); mkdirSync(from)\n  assert.throws(() => renamePath({from: parse(directory).root, to: join(directory, \"root\")}), hasCode(\"PATH_NOT_ALLOWED\"))\n  assert.throws(() => renamePath({from, to: join(from, \"nested\")}), hasCode(\"INVALID_INPUT\"))\n}))\ntest(\"rename moves a final symlink as a link\", () => fixture(directory => {\n  writeFileSync(join(directory, \"target\"), \"data\"); symlinkSync(\"target\", join(directory, \"link\"))\n  renamePath({from: join(directory, \"link\"), to: join(directory, \"moved\")})\n  assert.equal(readFileSync(join(directory, \"target\"), \"utf8\"), \"data\")\n  assert.equal(readFileSync(join(directory, \"moved\"), \"utf8\"), \"data\")\n}))\n",
  "filesystem/shared/files.ts": "import {createHash, randomUUID} from \"node:crypto\"\nimport {constants, openSync, closeSync, fstatSync, fchmodSync, readSync, lstatSync, writeFileSync, renameSync, unlinkSync} from \"node:fs\"\nimport {dirname, join} from \"node:path\"\nimport {ToolError} from \"../../shared/errors.ts\"\nimport type {FileEntry} from \"./types.ts\"\n\nexport const MAX_BYTES = 8 * 1024 * 1024\n\nexport function metadata(path: string): FileEntry {\n  const stat = lstatSync(path)\n  return {path, type: stat.isSymbolicLink() ? \"symlink\" : stat.isFile() ? \"file\" : stat.isDirectory() ? \"directory\" : \"other\",\n    size: stat.size, mode: stat.mode & 0o777, modifiedAt: stat.mtime.toISOString()}\n}\n\nexport function digest(data: Uint8Array): string {\n  return createHash(\"sha256\").update(data).digest(\"hex\")\n}\n\nexport function readChunk(path: string, offset: number, maxBytes: number): {data: Buffer; size: number} {\n  if (!lstatSync(path).isFile()) throw new ToolError(\"INVALID_PATH_TYPE\", \"Path must be a regular file\")\n  const fd = openSync(path, constants.O_RDONLY | constants.O_NOFOLLOW)\n  try {\n    const stat = fstatSync(fd)\n    if (!stat.isFile()) throw new ToolError(\"INVALID_PATH_TYPE\", \"Path must be a regular file\")\n    const buffer = Buffer.alloc(Math.max(0, Math.min(maxBytes, stat.size - offset)))\n    let bytes = 0\n    while (bytes < buffer.length) {\n      const count = readSync(fd, buffer, bytes, buffer.length - bytes, offset + bytes)\n      if (count === 0) break\n      bytes += count\n    }\n    return {data: buffer.subarray(0, bytes), size: stat.size}\n  } finally { closeSync(fd) }\n}\n\nexport function readWhole(path: string): Buffer {\n  const {data, size} = readChunk(path, 0, MAX_BYTES)\n  if (size > MAX_BYTES) throw new ToolError(\"LIMIT_EXCEEDED\", \"File exceeds the mutation byte limit\", 413)\n  if (data.length !== size) throw new ToolError(\"CONFLICT\", \"File changed while being read\", 409)\n  return data\n}\n\nexport function decode(content: string, encoding: \"utf8\" | \"base64\"): Buffer {\n  if (Buffer.byteLength(content, \"utf8\") > MAX_BYTES * 1.4) throw new ToolError(\"LIMIT_EXCEEDED\", \"Content exceeds the byte limit\", 413)\n  if (encoding === \"base64\" && (content.length % 4 !== 0 || !/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(content))) {\n    throw new ToolError(\"INVALID_INPUT\", \"Content must be canonical base64\")\n  }\n  const data = Buffer.from(content, encoding)\n  if (encoding === \"base64\" && data.toString(\"base64\") !== content) throw new ToolError(\"INVALID_INPUT\", \"Content must be canonical base64\")\n  if (data.length > MAX_BYTES) throw new ToolError(\"LIMIT_EXCEEDED\", \"Content exceeds the byte limit\", 413)\n  return data\n}\n\n/** Atomic replacement of one regular file, not a filesystem transaction or a cross-process CAS. */\nexport function replaceFile(path: string, data: Buffer, expectedHash?: string): void {\n  const stat = lstatSync(path)\n  if (!stat.isFile()) throw new ToolError(\"INVALID_PATH_TYPE\", \"Path must be a regular file\")\n  if (expectedHash !== undefined && digest(readWhole(path)) !== expectedHash) throw new ToolError(\"CONFLICT\", \"Content hash does not match\", 409)\n  const temporary = join(dirname(path), `.ai-tools-${randomUUID()}.tmp`)\n  try {\n    const fd = openSync(temporary, constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL, stat.mode & 0o777)\n    try {\n      writeFileSync(fd, data)\n      fchmodSync(fd, stat.mode & 0o777)\n    } finally { closeSync(fd) }\n    renameSync(temporary, path)\n  } finally {\n    try { unlinkSync(temporary) } catch (error) { if ((error as NodeJS.ErrnoException).code !== \"ENOENT\") throw error }\n  }\n}\n",
  "filesystem/shared/paths.ts": "import {lstatSync, realpathSync, statSync} from \"node:fs\"\nimport {basename, dirname, isAbsolute, join, parse, relative, resolve, sep} from \"node:path\"\nimport {ToolError} from \"../../shared/errors.ts\"\nimport {text} from \"../../shared/validation.ts\"\n\n/** Syntax only: no working directory, aliases, registration or filesystem access. */\nexport function absolutePath(value: unknown): string {\n  const path = text(value, \"path\")\n  if (!isAbsolute(path) || path.includes(\"\\0\") || Buffer.byteLength(path) > 4096) {\n    throw new ToolError(\"PATH_NOT_ALLOWED\", \"An absolute path of at most 4096 bytes without NUL is required\", 403)\n  }\n  return resolve(path)\n}\n\n/** Canonicalize existing parents, including system aliases such as macOS /tmp.\n * Final symlinks are rejected unless the operation explicitly works on the link.\n * This is path handling, not authorization or a race-proof OS sandbox. */\nexport function resolvePath(value: unknown, options: {missing?: boolean; finalSymlink?: boolean; mutable?: boolean} = {}): string {\n  const requested = absolutePath(value)\n  if (options.mutable && requested === parse(requested).root) {\n    throw new ToolError(\"PATH_NOT_ALLOWED\", \"The filesystem root cannot be changed\", 403)\n  }\n  let parent = dirname(requested)\n  const tail = [basename(requested)]\n  let canonical: string\n  while (true) {\n    try {\n      canonical = realpathSync(parent)\n      if (!statSync(canonical).isDirectory()) throw new ToolError(\"INVALID_PATH_TYPE\", \"A parent is not a directory\")\n      break\n    } catch (error) {\n      if (!options.missing || (error as NodeJS.ErrnoException).code !== \"ENOENT\" || parent === dirname(parent)) throw error\n      // A dangling parent symlink must not be mistaken for a missing directory.\n      try {\n        if (lstatSync(parent).isSymbolicLink()) throw new ToolError(\"PATH_NOT_ALLOWED\", \"A parent symlink has no target\", 403)\n      } catch (failure) { if ((failure as NodeJS.ErrnoException).code !== \"ENOENT\") throw failure }\n      tail.unshift(basename(parent))\n      parent = dirname(parent)\n    }\n  }\n  const path = join(canonical, ...tail)\n  try {\n    const stat = lstatSync(path)\n    if (stat.isSymbolicLink() && !options.finalSymlink) throw new ToolError(\"PATH_NOT_ALLOWED\", \"This operation does not follow a final symlink\", 403)\n  } catch (error) {\n    if (!options.missing || (error as NodeJS.ErrnoException).code !== \"ENOENT\") throw error\n  }\n  if (options.mutable && path === parse(path).root) throw new ToolError(\"PATH_NOT_ALLOWED\", \"The filesystem root cannot be changed\", 403)\n  return path\n}\n\nexport function within(directory: string, path: string): boolean {\n  const relation = relative(directory, path)\n  return relation !== \"..\" && !relation.startsWith(`..${sep}`) && !isAbsolute(relation)\n}\n",
  "filesystem/shared/spec-fixture.ts": "import {mkdtempSync, rmSync, realpathSync} from \"node:fs\"\nimport {tmpdir} from \"node:os\"\nimport {join} from \"node:path\"\n\nexport async function fixture<T>(run: (directory: string) => T | Promise<T>): Promise<T> {\n  const directory = realpathSync(mkdtempSync(join(tmpdir(), \"ai-tools-spec-\")))\n  try { return await run(directory) }\n  finally { rmSync(directory, {recursive: true, force: true}) }\n}\n\nexport function hasCode(code: string): (error: unknown) => boolean {\n  return error => (error as {code?: string} | null)?.code === code\n}\n",
  "filesystem/shared/types.ts": "export interface FileEntry {\n  path: string\n  type: \"file\" | \"directory\" | \"symlink\" | \"other\"\n  size: number\n  mode: number\n  modifiedAt: string\n}\n",
  "filesystem/stat/contract/input.ts": "/** Standalone tool input. Authorization belongs to the calling host. */\nexport interface StatPathInput {\n  /** Absolute path. The final symlink itself is described. */\n  path: string\n}\n",
  "filesystem/stat/contract/output.ts": "import type {FileEntry} from \"../../shared/types.ts\"\n\n/** Filesystem paths in results are absolute; no workspace identity is returned. */\nexport interface StatPathOutput {\n  entry: FileEntry\n}\n",
  "filesystem/stat/index.ts": "/**\n * Возвращает метаданные абсолютного пути, не разыменовывая конечный symlink.\n * @packageDocumentation\n */\nimport {object} from \"../../shared/validation.ts\"\nimport {resolvePath} from \"../shared/paths.ts\"\nimport {metadata} from \"../shared/files.ts\"\nimport type {StatPathInput} from \"./contract/input.ts\"\nimport type {StatPathOutput} from \"./contract/output.ts\"\nexport type {StatPathInput} from \"./contract/input.ts\"\nexport type {StatPathOutput} from \"./contract/output.ts\"\n\nexport function statPath(input: StatPathInput): StatPathOutput {\n  object(input, [\"path\"])\n  return {entry: metadata(resolvePath(input.path, {finalSymlink: true}))}\n}\n",
  "filesystem/stat/spec/scenario.spec.ts": "import {test} from \"node:test\"\nimport assert from \"node:assert/strict\"\nimport {writeFileSync, readFileSync, mkdirSync, symlinkSync, existsSync, chmodSync, statSync, readdirSync} from \"node:fs\"\nimport {join, parse} from \"node:path\"\nimport {fixture, hasCode} from \"../../shared/spec-fixture.ts\"\nimport {statPath} from \"../index.ts\"\n\ntest(\"stat reports file and directory metadata by absolute path\", () => fixture(directory => {\n  const path = join(directory, \"file.txt\")\n  writeFileSync(path, \"abc\")\n  assert.equal(statPath({path}).entry.size, 3)\n  assert.equal(statPath({path: directory}).entry.type, \"directory\")\n  assert.equal(statPath({path}).entry.path, path)\n}))\ntest(\"stat describes a terminal symlink without exposing its target\", () => fixture(directory => {\n  symlinkSync(\"missing-outside-target\", join(directory, \"link\"))\n  const result = statPath({path: join(directory, \"link\")})\n  assert.equal(result.entry.type, \"symlink\")\n  assert.equal(JSON.stringify(result).includes(\"outside-target\"), false)\n}))\ntest(\"stat has no hard-coded Git metadata policy\", () => fixture(directory => {\n  mkdirSync(join(directory, \".git\"))\n  writeFileSync(join(directory, \".git/config\"), \"x\")\n  assert.equal(statPath({path: join(directory, \".git/config\")}).entry.size, 1)\n}))\n",
  "filesystem/write/contract/input.ts": "/** Standalone tool input. Authorization belongs to the calling host. */\nexport interface WriteFileInput {\n  /** Absolute path of an existing regular file. */\n  path: string\n  content: string\n  encoding?: \"utf8\" | \"base64\"\n  /** Lowercase SHA-256; conflict detection, not a cross-process lock. */\n  expectedHash?: string\n}\n",
  "filesystem/write/contract/output.ts": "/** Filesystem paths in results are absolute; no workspace identity is returned. */\nexport interface WriteFileOutput {\n  path: string\n  bytes: number\n  contentHash: string\n}\n",
  "filesystem/write/index.ts": "/**\n * Атомарно заменяет существующий обычный файл. expectedHash проверяет прежнее содержимое, но не является блокировкой.\n * @packageDocumentation\n */\nimport {object, text, encoding, hash} from \"../../shared/validation.ts\"\nimport {resolvePath} from \"../shared/paths.ts\"\nimport {decode, digest, replaceFile} from \"../shared/files.ts\"\nimport type {WriteFileInput} from \"./contract/input.ts\"\nimport type {WriteFileOutput} from \"./contract/output.ts\"\nexport type {WriteFileInput} from \"./contract/input.ts\"\nexport type {WriteFileOutput} from \"./contract/output.ts\"\n\nexport function writeFile(input: WriteFileInput): WriteFileOutput {\n  object(input, [\"path\", \"content\", \"encoding\", \"expectedHash\"])\n  const data = decode(text(input.content, \"content\", true), encoding(input.encoding))\n  const expected = hash(input.expectedHash)\n  const path = resolvePath(input.path, {mutable: true})\n  replaceFile(path, data, expected)\n  return {path, bytes: data.length, contentHash: digest(data)}\n}\n",
  "filesystem/write/spec/scenario.spec.ts": "import {test} from \"node:test\"\nimport assert from \"node:assert/strict\"\nimport {writeFileSync, readFileSync, mkdirSync, symlinkSync, existsSync, chmodSync, statSync, readdirSync} from \"node:fs\"\nimport {join, parse} from \"node:path\"\nimport {fixture, hasCode} from \"../../shared/spec-fixture.ts\"\nimport {writeFile} from \"../index.ts\"\nimport {readFile} from \"../../read/index.ts\"\n\ntest(\"write replaces a file and preserves its permissions\", () => fixture(directory => {\n  const path = join(directory, \"file\")\n  writeFileSync(path, \"before\"); chmodSync(path, 0o660)\n  const result = writeFile({path, content: \"after\"})\n  assert.equal(readFileSync(path, \"utf8\"), \"after\")\n  assert.equal(result.bytes, 5)\n  assert.equal(statSync(path).mode & 0o777, 0o660)\n  assert.deepEqual(readdirSync(directory), [\"file\"])\n}))\ntest(\"write rejects stale expectedHash without changing contents\", () => fixture(directory => {\n  const path = join(directory, \"file\")\n  writeFileSync(path, \"before\")\n  const expectedHash = readFile({path}).contentHash!\n  writeFile({path, content: \"after\", expectedHash})\n  assert.throws(() => writeFile({path, content: \"bad\", expectedHash}), hasCode(\"CONFLICT\"))\n  assert.equal(readFileSync(path, \"utf8\"), \"after\")\n}))\ntest(\"write accepts empty contents but does not create missing files\", () => fixture(directory => {\n  const path = join(directory, \"file\")\n  writeFileSync(path, \"before\"); writeFile({path, content: \"\"})\n  assert.equal(statSync(path).size, 0)\n  assert.throws(() => writeFile({path: join(directory, \"missing\"), content: \"\"}), hasCode(\"ENOENT\"))\n}))\ntest(\"write rejects symlinks and non-canonical base64\", () => fixture(directory => {\n  const path = join(directory, \"file\")\n  writeFileSync(path, \"before\"); symlinkSync(\"file\", join(directory, \"link\"))\n  assert.throws(() => writeFile({path: join(directory, \"link\"), content: \"bad\"}), hasCode(\"PATH_NOT_ALLOWED\"))\n  for (const content of [\"abc\", \"!!!!\", \"Zh==\"]) assert.throws(() => writeFile({path, content, encoding: \"base64\"}), hasCode(\"INVALID_INPUT\"))\n  assert.equal(readFileSync(path, \"utf8\"), \"before\")\n}))\ntest(\"write rejects removed root input before touching a file\", () => fixture(directory => {\n  const path = join(directory, \"file\"); writeFileSync(path, \"before\")\n  assert.throws(() => writeFile({path, content: \"bad\", root: \"repo\"} as never), hasCode(\"INVALID_INPUT\"))\n  assert.equal(readFileSync(path, \"utf8\"), \"before\")\n}))\n",
  "git/package.json": "{\n  \"name\": \"@ai/git\",\n  \"label\": \"Git\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"exports\": {\n    \"./status\": \"./status/index.ts\"\n  }\n}\n",
  "git/README.md": "# Git\n\nstatus({path, maxEntries?}) читает состояние checkout по абсолютному пути.\nНет файлового контекста, регистрации, roots/open или UI selector. В указанной\nдиректории должна быть собственная .git; поиск checkout в предках не выполняется.\nИмена файлов в entries остаются относительными к checkout, общий path абсолютный.\n\nКоманда и аргументы фиксированы, shell не используется. Наследуемые GIT_*\nпеременные исключены, fsmonitor и необязательные блокировки отключены.\nВывод ограничен 1 MiB, выполнение — 10 секундами. Превышение лимита или timeout\nне выдаются за успешный результат. maxEntries ограничивает уже разобранный\nрезультат с truncated:true. Пробелы/переводы строк и rename разбираются по NUL.\n\nКонтракты — status/contract/, тесты — status/spec/scenario.spec.ts.\nlog, diff, show, blame, commit, push и изменение индекса не добавлены этим этапом.\n",
  "git/status/contract/input.ts": "/** Read-only Git operation. No registration, session or workspace context. */\nexport interface GitStatusInput {\n  /** Absolute checkout directory containing .git. Ancestor repositories are not selected implicitly. */\n  path: string\n  /** Default 1000; range 1..5000. */\n  maxEntries?: number\n}\n",
  "git/status/contract/output.ts": "export interface GitStatusOutput {\n  /** Absolute checkout path; entry paths retain Git's checkout-relative format. */\n  path: string\n  branch: string\n  entries: {index: string; worktree: string; path: string; originalPath?: string}[]\n  truncated: boolean\n}\n",
  "git/status/index.ts": "/**\n * Читает Git status checkout по абсолютному пути без shell и произвольных аргументов.\n * @remarks Вывод ограничен 1 MiB, выполнение — 10 секундами. Не запускает commit/push.\n * @packageDocumentation\n */\nimport {spawnSync} from \"node:child_process\"\nimport {lstatSync} from \"node:fs\"\nimport {join, dirname} from \"node:path\"\nimport {ToolError} from \"../../shared/errors.ts\"\nimport {object, integer} from \"../../shared/validation.ts\"\nimport {resolvePath} from \"../../filesystem/shared/paths.ts\"\nimport type {GitStatusInput} from \"./contract/input.ts\"\nimport type {GitStatusOutput} from \"./contract/output.ts\"\nexport type {GitStatusInput} from \"./contract/input.ts\"\nexport type {GitStatusOutput} from \"./contract/output.ts\"\n\nexport function gitStatus(input: GitStatusInput): GitStatusOutput {\n  object(input, [\"path\", \"maxEntries\"])\n  const path = resolvePath(input.path)\n  const maxEntries = integer(input.maxEntries, 1000, 1, 5000, \"maxEntries\")\n  let gitMetadata\n  try { gitMetadata = lstatSync(join(path, \".git\")) } catch { throw new ToolError(\"NOT_A_REPOSITORY\", \"The path is not a Git checkout\", 400) }\n  if (gitMetadata.isSymbolicLink() || (!gitMetadata.isFile() && !gitMetadata.isDirectory())) throw new ToolError(\"NOT_A_REPOSITORY\", \"Git metadata has an unsupported type\", 400)\n  const env = Object.fromEntries(Object.entries(process.env).filter(([key]) => !key.startsWith(\"GIT_\")))\n  const result = spawnSync(\"git\", [\"--no-optional-locks\", \"-c\", \"core.fsmonitor=false\", \"status\", \"--porcelain=v1\", \"-z\", \"--branch\", \"--untracked-files=normal\"], {\n    cwd: path, encoding: \"utf8\", timeout: 10000, maxBuffer: 1024 * 1024,\n    env: {...env, GIT_TERMINAL_PROMPT: \"0\", GIT_CEILING_DIRECTORIES: dirname(path)},\n  })\n  if ((result.error as NodeJS.ErrnoException | undefined)?.code === \"ETIMEDOUT\") throw new ToolError(\"TIMEOUT\", \"Git status exceeded its execution budget\", 504)\n  if ((result.error as NodeJS.ErrnoException | undefined)?.code === \"ENOBUFS\") throw new ToolError(\"LIMIT_EXCEEDED\", \"Git status exceeded its output budget\", 413)\n  if (result.error !== undefined || result.status !== 0) throw new ToolError(\"GIT_ERROR\", \"Git status failed\", 502)\n  const records = result.stdout.split(\"\\0\")\n  const header = records.shift() ?? \"\"\n  if (!header.startsWith(\"## \")) throw new ToolError(\"GIT_ERROR\", \"Unexpected Git status header\", 502)\n  const entries: GitStatusOutput[\"entries\"] = []\n  let truncated = false\n  for (let i = 0; i < records.length; i++) {\n    const record = records[i]!\n    if (record === \"\") continue\n    if (entries.length >= maxEntries) { truncated = true; break }\n    if (record.length < 4 || record[2] !== \" \") throw new ToolError(\"GIT_ERROR\", \"Unexpected Git status record\", 502)\n    const index = record[0]!\n    const worktree = record[1]!\n    const renamed = [index, worktree].some(status => status === \"R\" || status === \"C\")\n    const originalPath = renamed ? records[++i] : undefined\n    if (renamed && !originalPath) throw new ToolError(\"GIT_ERROR\", \"Incomplete Git rename record\", 502)\n    entries.push({index, worktree, path: record.slice(3), ...(originalPath === undefined ? {} : {originalPath})})\n  }\n  return {path, branch: header.slice(3), entries, truncated}\n}\n",
  "git/status/spec/scenario.spec.ts": "import {test} from \"node:test\"\nimport assert from \"node:assert/strict\"\nimport {spawnSync} from \"node:child_process\"\nimport {writeFileSync, mkdirSync} from \"node:fs\"\nimport {join} from \"node:path\"\nimport {gitStatus} from \"../index.ts\"\nimport {fixture, hasCode} from \"../../../filesystem/shared/spec-fixture.ts\"\n\ntest(\"status reads untracked names without shell parsing\", () => fixture(directory => {\n  assert.equal(spawnSync(\"git\", [\"init\", \"-q\"], {cwd: directory}).status, 0)\n  writeFileSync(join(directory, \"unusual name\\n.txt\"), \"data\")\n  const result = gitStatus({path: directory})\n  assert.equal(result.entries[0]?.path, \"unusual name\\n.txt\")\n  assert.equal(result.entries[0]?.index, \"?\")\n  assert.equal(result.truncated, false)\n  assert.equal(result.path, directory)\n}))\ntest(\"status parses staged renames as destination then source\", () => fixture(directory => {\n  const git = (...args: string[]): void => {assert.equal(spawnSync(\"git\", args, {cwd: directory, env: {...process.env, GIT_AUTHOR_NAME: \"Test\", GIT_AUTHOR_EMAIL: \"test@example.invalid\", GIT_COMMITTER_NAME: \"Test\", GIT_COMMITTER_EMAIL: \"test@example.invalid\"}}).status, 0)}\n  git(\"init\", \"-q\")\n  writeFileSync(join(directory, \"old name\"), \"unchanged contents\")\n  git(\"add\", \".\"); git(\"-c\", \"commit.gpgsign=false\", \"commit\", \"-qm\", \"fixture\"); git(\"mv\", \"old name\", \"new name\")\n  const result = gitStatus({path: directory})\n  assert.equal(result.entries[0]?.path, \"new name\")\n  assert.equal(result.entries[0]?.originalPath, \"old name\")\n}))\ntest(\"status never falls back to an ancestor repository\", () => fixture(directory => {\n  assert.equal(spawnSync(\"git\", [\"init\", \"-q\"], {cwd: directory}).status, 0)\n  mkdirSync(join(directory, \"nested\"))\n  assert.throws(() => gitStatus({path: join(directory, \"nested\")}), hasCode(\"NOT_A_REPOSITORY\"))\n}))\ntest(\"status reports a bounded result\", () => fixture(directory => {\n  assert.equal(spawnSync(\"git\", [\"init\", \"-q\"], {cwd: directory}).status, 0)\n  writeFileSync(join(directory, \"a\"), \"a\"); writeFileSync(join(directory, \"b\"), \"b\")\n  const result = gitStatus({path: directory, maxEntries: 1})\n  assert.equal(result.entries.length, 1)\n  assert.equal(result.truncated, true)\n}))\n",
  "INTEGRATION.md": "# Подготовка интеграции в Завхоз\n\nАвтор: zavx0z. Объём этого изменения — только репозиторий ai. Ai-macos,\nустановленный Runtime, proxy, tunnel и рабочие каталоги Mac не изменялись.\n\n## Фактическая граница принимающей стороны\n\nПроверен опубликованный ai-macos на\n62b0135d796fe738587ce4a4650ecd09fb40c21a, не установленная версия Mac:\n\n- mcp/src/chat-proxy.ts: один вход zavx0z; сервисы computer/knowledge создаются\n  через createLazyServices. Пустой action раскрывает справку, явный — выполняет.\n- mcp/src/service-client.ts: ServiceRegistration.create возвращает ServiceClient\n  с listTools/getTool/call/close; getTool возвращает MCP Tool с JSON Schema.\n- mcp/src/chat-executor.ts: существующий computer-клиент проверяет hostname,\n  Runtime health и вызывает текущий Runtime через UDS; нет повторов операций.\n\nВ ai доступны прямые функции и createDispatcher из server/dispatch/index.ts.\nЕго импорт не запускает сервис. Можно использовать существующий процесс Завхоза,\nне поднимать второй Runtime, отдельный MCP или дополнительный HTTP listener.\n\n## Что уже можно подключать\n\nЗапросы ai/filesystem/read, ai/filesystem/write и остальных функций имеют\nnode/action/input; описания, TypeScript-контракты и исходники сценариев раскрываются\nпо запросу. Разрешение — callback хоста; отсутствующее разрешение закрывает run.\nСодержимое input копируется и глубоко замораживается до ожидания callback.\n\nКонфигурация repositoryRoot у dispatcher указывает на установленные исходники\nсамого ai для discovery. Это не рабочий проект и не разрешённый корень файлов.\nПри упаковке должны сохраняться package.json, exports, contract и spec рядом\nс кодом, либо принимающая сторона должна явно обеспечить тот же источник метаданных.\nПользовательский node никогда не становится произвольным путём import.\n\n## Что ещё сделать в ai-macos\n\nНужен небольшой ServiceClient-адаптер и регистрация ai в существующем ленивом\nкаталоге. Это отдельное изменение принимающей стороны, не выполненное здесь.\nНельзя объявлять текущий dispatcher готовым drop-in ServiceClient:\ngetTool в Завхозе ожидает JSON Schema, а ai раскрывает TypeScript-исходники.\nНужно согласовать преобразование/обёртку без ручного дублирования контрактов\nи сопоставление адресов/действий; существующий proxy не обязан понимать run\nна структурном адресе ai/filesystem/read без такого адаптера.\n\nПеред каждым исполнением принимающий хост должен подтвердить ожидаемую машину\nи полномочия именно файловой операции. Подтверждение UI-ввода не означает\nразрешение на файловую запись, commit или установку. authorize может проверить\nnode, замороженный input, effect и paths. Для patch paths содержит directory;\nвесь patch доступен в input для более узкого допуска по отдельным файлам.\nПроверки путей самой библиотеки не устанавливают пользовательские полномочия.\n\nСуществующие signal/receipt/operation механизмы нужно сохранить. Синхронный файловый\nвызов не является отменяемой фоновой операцией; прерывание ожидания не доказывает\nотсутствия побочного эффекта. После unknown/partial читать реальный результат,\nне повторять mutation. Ошибку PARTIAL_FAILURE не превращать в полный успех.\n\n## Критерий следующего этапа\n\nЧерез один zavx0z открыть контракт и выполнить разрешённые read → write с\nexpectedHash → read на отдельной временной директории той же подтверждённой\nмашины. Отказ разрешения не меняет файл; старый hash даёт конфликт; другой\nсервис и его viewer продолжают работать. Добавить тесты несовместимых полномочий,\nотмены/неизвестного исхода и упаковки метаданных. Только затем отдельно согласовать\nустановку с независимым путём возврата, не останавливая рабочий канал через себя.\n",
  "MIGRATION.md": "# Переход к универсальным инструментам\n\n## Решение\n\nПо поручению Владимира убраны roots/open и workspace-модель из ai. Это изменение\nAPI поверх main 15cc36832aa570be7cbb8fa1fc76cd46a889e535, не переписывание истории.\nПредыдущая программа переноса runtime/debugger Interpreter больше не является\nобъёмом этого репозитория. Никакого замещающего runtime здесь не добавлено.\n\n## Несовместимое изменение\n\nРаньше функции принимали {root: alias, ...} и второй FilesystemOutput от\ncreateFilesystem. Теперь они принимают один Input с абсолютным path либо from/to.\nread-many принимает paths, которые могут находиться в разных директориях.\napply-patch принимает directory для относительных путей внутри текста patch.\ngit/status принимает path конкретного checkout. Файловые результаты возвращают\nабсолютные пути; Git entries по-прежнему относительны к checkout.\n\nУдалены публичные roots/open, фабрика createFilesystem, её Input/Output и тесты.\nУдалены bindings с захваченным файловым контекстом; единственные привязки функций\nнаходятся в server/dispatch/src/bindings.ts. Старый root не принимается скрытно.\n\nУниверсальные функции не скрывают .git. Они канонизируют существующие родительские\nпути и не разыменовывают конечный symlink; stat/remove/rename работают с самой\nссылкой. Политика каталогов перенесена к необязательному HTTP-хосту, не дублируется\nв каждой туле. Его AI_TOOLS_ALLOWED_DIRECTORIES — явный список абсолютных путей.\nСтарый AI_TOOLS_ROOTS не конвертируется автоматически и не расширяет прежние права.\n\n## Встраивание\n\ncreateDispatcher предоставляет описание/контракт/сценарий и явный run без HTTP\nlistener или MCP runtime. Выполнение требует разрешения вызывающего хоста.\nТот же dispatcher используется HTTP-адаптером. Термин исправлен на lazy MCP.\n\nЭто подготовка универсальных функций и точки входа, не переключение работающего\nЗавхоза. Несовпадение текущего ServiceClient и TypeScript-контрактов описано в\nINTEGRATION.md; установленная интеграция не объявляется готовой.\n\n## История и проверка\n\nНа 16 сентября предыдущий этап фиксировал 12 файловых функций + Git status и\n73 Node-сценария. Это исторический результат исходного коммита, не повторный\nпрогон всех прежних тестов сейчас. Раньше runtime/debugger оставались в Interpreter;\nтеперь их перенос сюда исключён из задачи, а не выдан за выполненный.\nТекущие проверки и известные ограничения — в VERIFICATION.md.\n",
  "package.json": "{\n  \"name\": \"@zavx0z/ai\",\n  \"label\": \"AI Tools\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"workspaces\": [\n    \"filesystem\",\n    \"git\",\n    \"server\"\n  ],\n  \"scripts\": {\n    \"start\": \"bun server/index.ts\",\n    \"start:node\": \"node --experimental-strip-types server/index.ts\",\n    \"test\": \"bun test\",\n    \"test:node\": \"node --experimental-strip-types --test filesystem/*/spec/scenario.spec.ts git/*/spec/scenario.spec.ts server/*/spec/scenario.spec.ts\",\n    \"check\": \"tsc --noEmit\"\n  },\n  \"devDependencies\": {\n    \"@types/node\": \"22.19.7\",\n    \"typescript\": \"5.8.3\"\n  },\n  \"engines\": {\n    \"node\": \">=22.6.0\"\n  }\n}\n",
  "README.md": "# AI Tools\n\nУниверсальные TypeScript-инструменты для файлов и Git. **10 файловых операций\nи Git status**, без workspace/session-модели, регистрации корней, `roots`,\n`open` и зависимостей от Interpreter. Подготовлены для встраивания в существующий\n`zavx0z` (Завхоз); установленный плагин этим репозиторием не переключается.\n\n## Прямые функции\n\nКаждая функция принимает только свой Input. Второго аргумента-контекста нет.\nПути — абсолютные пути файловой системы, а не aliases. Текущий каталог процесса\nне подставляется. Результаты файловых операций также содержат абсолютные пути.\n\n```ts\nimport {readFile} from \"./filesystem/read/index.ts\"\nimport {writeFile} from \"./filesystem/write/index.ts\"\nimport {renamePath} from \"./filesystem/rename/index.ts\"\n\nconst file = readFile({path: \"/work/project/src/index.ts\"})\n// Полный contentHash доступен только при чтении всего файла.\nwriteFile({path: file.path, content: \"new contents\\n\", expectedHash: file.contentHash!})\nrenamePath({from: \"/work/project/a.ts\", to: \"/work/another/b.ts\"})\n```\n\nФайловые инструменты: `stat`, `list`, `read`, `read-many`, `write`, `create`,\n`mkdir`, `remove`, `rename`, `apply-patch`. Git: `status`.\n`apply-patch` принимает `{directory, patch, dryRun?}`: директория задаёт базу\nотносительных путей внутри патча, но не регистрирует workspace.\n`git/status` принимает `{path, maxEntries?}`, где path — директория checkout.\n\n## Структура и lazy MCP\n\nУ каждой операции собственные `index.ts`, `contract/input.ts`,\n`contract/output.ts`, `spec/scenario.spec.ts`. Общие механизмы находятся у общего\nвладельца в `shared/`. `workspaces` в package.json — сборочная структура пакетов,\nне состояние рабочих проектов. `exports` задают публичные входы.\n\n`server/dispatch` предоставляет общий lazy-вход без запуска сервера или MCP:\n\n```ts\nimport {createDispatcher} from \"./server/dispatch/index.ts\"\n\nconst tools = createDispatcher({\n  repositoryRoot: \"/installed/ai\", // исходники описаний и контрактов\n  authorize: invocation => hostPolicy.authorize(invocation), // политика вызывающего хоста\n})\n\nawait tools.dispatch({node: \"ai/filesystem/read\", input: {view: \"contract\"}})\nawait tools.dispatch({\n  node: \"ai/filesystem/read\", action: \"run\",\n  input: {path: \"/work/project/src/index.ts\"},\n})\n```\n\n`hostPolicy` в примере — зависимость интегрирующего хоста, не поставляемая\nздесь заглушка. Без authorize разрешено описание, но **любое выполнение запрещено**.\nCallback должен вернуть именно true; false, undefined или исключение не запускают\nтулу. Аргументы копируются и замораживаются до ожидания разрешения.\n\nБез action возвращается описание; `input.view: \"contract\"` раскрывает исходный\nTypeScript, `\"scenarios\"` — исходник теста с `executed:false`. Только `action:\"run\"`\nвызывает явно подключённую функцию. Произвольного import, shell или выбора\nисполняемого файла по адресу node нет. Технические узлы сервера не исполняются.\nЭто lazy MCP, не отдельный продукт или SDK с другим названием.\n\n## Необязательный HTTP-вход\n\nДля встраивания в Завхоз он не нужен. Для отдельного доверенного HTTP-хоста:\n\n```sh\nbun install\nexport AI_TOOLS_ALLOWED_DIRECTORIES='[\"/absolute/path/to/project\"]'\nexport AI_TOOLS_TOKEN=\"$(openssl rand -hex 32)\"\nbun run start\n# Альтернатива: npm run start:node\n```\n\nПо умолчанию `http://127.0.0.1:8787/tools`; адрес меняется через AI_TOOLS_HOST\nи AI_TOOLS_PORT. `.env` автоматически не загружается. Нужны Bun либо Node.js 22.6+;\nдля status — установленный Git. Исполнение использует только стандартные модули.\n\nGET /tools и POST /tools с {} возвращают обзор. Все запросы требуют\n`Authorization: Bearer <token>`. POST принимает ту же оболочку node/action/input.\nHTTP разрешает только пути внутри явно заданных директорий, проверяя физические\nродительские пути и оба конца rename. Это политика хоста, не аргумент тулов.\nAI_TOOLS_ROOTS больше не принимается: старые разрешения не расширяются молча.\n\n## Границы\n\nПрямые функции используют права вызывающего процесса. Это не OS sandbox и не\nгарантия против враждебного локального процесса, меняющего пути между проверкой\nи системным вызовом. Проверка expectedHash — защита от устаревшего содержимого,\nне межпроцессная блокировка. `.git` для универсальных файловых функций является\nобычным каталогом; решение разрешить доступ принадлежит вызывающему хосту.\n\nЛимиты байтов, исключительное создание, запрет неявной рекурсии и перезаписи,\nпроверка патча и защита корня файловой системы сохранены. Частичный patch\nвозвращает PARTIAL_FAILURE с completed/current/cause, не обещание отката.\nПосле неизвестного результата нельзя автоматически повторять изменение.\n\nHTTP сохраняет Bearer-проверку, запрет браузерного Origin и лимит тела 12 MiB.\nСодержимое файлов, входные аргументы и токены не пишутся в диагностический JSONL.\nДля удалённого доступа нужен отдельно настроенный TLS-транспорт.\n\n## Проверка и интеграция\n\n```sh\nbun run check\nbun test\nnpm run test:node\n```\n\nПроверки используют только собственные временные директории. Результат этого\nэтапа и ограничения среды — в [VERIFICATION.md](VERIFICATION.md).\nПереход со старого API — в [MIGRATION.md](MIGRATION.md).\nГраница подключения к фактическому Завхозу — в [INTEGRATION.md](INTEGRATION.md).\nБраузер, UI, debugger, replay, процессы Interpreter и самостоятельный MCP runtime\nне являются частью этого репозитория или отложенным обязательством его переноса.\n",
  "server/contract/input.ts": "/** Optional HTTP listener configuration, not universal tool arguments. */\nexport interface ServerInput {\n  /** Absolute allowed directories. No aliases or tool-visible registration. Required to avoid widening an old configuration silently. */\n  allowedDirectories: string[]\n  token: string\n  hostname?: string\n  /** Default 8787; 0 asks the OS for a free port in integration tests. */\n  port?: number\n  repositoryRoot?: string\n  log?: boolean\n}\n",
  "server/contract/output.ts": "export interface ServerOutput {\n  url: string\n  close(): Promise<void>\n}\n",
  "server/discovery/contract/input.ts": "/** Trusted source checkout used only for structural metadata. It is not a filesystem tool root. */\nexport interface DiscoveryInput {\n  repositoryRoot: string\n  /** Доверенный источник упакованных текстовых метаданных. */\n  readSource?: (name: string, optional?: boolean) => string | null\n  runnable: ReadonlySet<string>\n}\n",
  "server/discovery/contract/output.ts": "/** Lazy structural descriptions; reading a contract or scenario never executes it. */\nexport interface DiscoveryOutput {\n  describe(node?: string, view?: string): unknown\n  has(node: string): boolean\n}\n",
  "server/discovery/index.ts": "/**\n * Раскрывает package.json workspaces/exports и локальные контракты выбранного узла.\n * @remarks TypeScript читается как текст, а не исполняется. Контракты и сценарии\n * загружаются только по запросу. Не является копией runtime Storybook.\n * @packageDocumentation\n */\nimport {realpathSync} from \"node:fs\"\nimport {dirname} from \"node:path\"\nimport {ToolError} from \"../../shared/errors.ts\"\nimport {source as fileSource, overview} from \"./src/read.ts\"\nimport type {DiscoveryInput} from \"./contract/input.ts\"\nimport type {DiscoveryOutput} from \"./contract/output.ts\"\nexport type {DiscoveryInput} from \"./contract/input.ts\"\nexport type {DiscoveryOutput} from \"./contract/output.ts\"\n\nexport function createDiscovery(input: DiscoveryInput): DiscoveryOutput {\n  const root = input.readSource ? input.repositoryRoot : realpathSync(input.repositoryRoot)\n  const source = (root: string, name: string, optional = false) => input.readSource\n    ? input.readSource(name, optional) : fileSource(root, name, optional)\n  const manifest = JSON.parse(source(root, \"package.json\")!) as {name: string; label?: string; workspaces: string[]}\n  const rootNode = manifest.name.split(\"/\").at(-1)!\n  if (!/^[a-z][a-z0-9-]*$/.test(rootNode) || !Array.isArray(manifest.workspaces)) throw new ToolError(\"INVALID_STRUCTURE\", \"Invalid root manifest\", 500)\n  const nodes = new Map<string, {name: string; label: string; directory: string; entry?: string; package: boolean}>()\n  nodes.set(rootNode, {name: manifest.name, label: manifest.label ?? rootNode, directory: \".\", package: true})\n  for (const directory of manifest.workspaces) {\n    if (!/^[a-z][a-z0-9-]*$/.test(directory)) throw new ToolError(\"INVALID_STRUCTURE\", \"Workspaces must be explicit root directories\", 500)\n    const pkg = JSON.parse(source(root, `${directory}/package.json`)!) as {name: string; label?: string; exports?: Record<string, string>}\n    const node = `${rootNode}/${directory}`\n    nodes.set(node, {name: pkg.name, label: pkg.label ?? directory, directory, package: true})\n    for (const [key, entry] of Object.entries(pkg.exports ?? {})) {\n      if (key === \".\") continue\n      if (!/^\\.\\/[a-z0-9-]+(?:\\/[a-z0-9-]+)*$/.test(key) || entry !== `${key}/index.ts`) throw new ToolError(\"INVALID_STRUCTURE\", \"Tools require explicit structural index.ts exports\", 500)\n      const segments = key.slice(2).split(\"/\")\n      for (let length = 1; length < segments.length; length++) {\n        const suffix = segments.slice(0, length).join(\"/\")\n        const category = `${node}/${suffix}`\n        if (!nodes.has(category)) nodes.set(category, {name: segments[length - 1]!, label: segments[length - 1]!, directory: `${directory}/${suffix}`, entry: `${directory}/${suffix}/index.ts`, package: false})\n      }\n      const address = `${node}/${key.slice(2)}`\n      nodes.set(address, {name: key.slice(2), label: key.slice(2), directory: `${directory}/${dirname(entry)}`, entry: `${directory}/${entry}`, package: false})\n    }\n  }\n  for (const address of input.runnable) if (!nodes.has(address)) throw new ToolError(\"INVALID_STRUCTURE\", \"An executable binding has no public export\", 500)\n  return {\n    has: node => nodes.has(node),\n    describe: (node = rootNode, view = \"overview\") => {\n      if (typeof node !== \"string\" || node.length > 256 || !nodes.has(node)) throw new ToolError(\"UNKNOWN_NODE\", \"Unknown structural node\", 404)\n      const owner = nodes.get(node)!\n      if (view === \"contract\") {\n        const inputSource = source(root, `${owner.directory}/contract/input.ts`, true)\n        const outputSource = source(root, `${owner.directory}/contract/output.ts`, true)\n        if (inputSource === null && outputSource === null) throw new ToolError(\"VIEW_NOT_FOUND\", \"This node has no contract\", 404)\n        return {node, view, format: \"typescript\", input: inputSource, output: outputSource}\n      }\n      if (view === \"scenarios\") {\n        const scenario = source(root, `${owner.directory}/spec/scenario.spec.ts`, true)\n        if (scenario === null) throw new ToolError(\"VIEW_NOT_FOUND\", \"This node has no scenarios\", 404)\n        return {node, view, format: \"typescript\", executed: false, source: scenario}\n      }\n      if (view !== \"overview\") throw new ToolError(\"VIEW_NOT_FOUND\", \"Unknown view\", 404)\n      const children = [...nodes.entries()].filter(([address]) => address.startsWith(`${node}/`) && !address.slice(node.length + 1).includes(\"/\"))\n        .map(([address, child]) => ({node: address, label: child.label, runnable: input.runnable.has(address)}))\n      const description = owner.package ? source(root, `${owner.directory}/README.md`, true) : overview(source(root, owner.entry!, true))\n      const views = [\"overview\"]\n      if (source(root, `${owner.directory}/contract/input.ts`, true) !== null || source(root, `${owner.directory}/contract/output.ts`, true) !== null) views.push(\"contract\")\n      if (source(root, `${owner.directory}/spec/scenario.spec.ts`, true) !== null) views.push(\"scenarios\")\n      return {node, name: owner.name, label: owner.label, description, runnable: input.runnable.has(node), children,\n        actions: input.runnable.has(node) ? [\"run\"] : [], views}\n    },\n  }\n}\n",
  "server/discovery/spec/scenario.spec.ts": "import {test} from \"node:test\"\nimport assert from \"node:assert/strict\"\nimport {readFileSync, writeFileSync, mkdirSync, existsSync} from \"node:fs\"\nimport {join} from \"node:path\"\nimport {createDiscovery} from \"../index.ts\"\nimport {bindings} from \"../../dispatch/src/bindings.ts\"\nimport {fixture, hasCode} from \"../../../filesystem/shared/spec-fixture.ts\"\nimport {repositoryRoot} from \"../../request/spec/fixture.ts\"\n\ntest(\"all eleven bindings have colocated contracts and executable scenarios\", () => {\n  const handlers = bindings()\n  assert.equal(handlers.size, 11)\n  for (const node of handlers.keys()) {\n    const path = node.split(\"/\").slice(1).join(\"/\")\n    for (const file of [\"index.ts\", \"contract/input.ts\", \"contract/output.ts\", \"spec/scenario.spec.ts\"]) {\n      assert.equal(existsSync(join(repositoryRoot, path, file)), true, `${node}/${file}`)\n    }\n  }\n  const discovery = createDiscovery({repositoryRoot, runnable: new Set(handlers.keys())})\n  assert.equal(discovery.has(\"ai/filesystem/read\"), true)\n  for (const node of [\"ai/filesystem/roots\", \"ai/filesystem/open\", \"ai/filesystem/shared\"]) {\n    assert.equal(discovery.has(node), false)\n    assert.throws(() => discovery.describe(node), hasCode(\"UNKNOWN_NODE\"))\n  }\n})\ntest(\"discovery supports nested addresses without executing source\", () => fixture(directory => {\n  writeFileSync(join(directory, \"package.json\"), JSON.stringify({name: \"@test/ai\", workspaces: [\"filesystem\"]}))\n  mkdirSync(join(directory, \"filesystem/group/tool\"), {recursive: true})\n  writeFileSync(join(directory, \"filesystem/package.json\"), JSON.stringify({name: \"@test/filesystem\", exports: {\"./group/tool\": \"./group/tool/index.ts\"}}))\n  writeFileSync(join(directory, \"filesystem/group/tool/index.ts\"), \"/** Safe description. @packageDocumentation */\\nthrow new Error('must not execute')\\n\")\n  const discovery = createDiscovery({repositoryRoot: directory, runnable: new Set([\"ai/filesystem/group/tool\"])})\n  const category = discovery.describe(\"ai/filesystem/group\") as {children: Array<{node: string}>}\n  assert.equal(category.children[0]?.node, \"ai/filesystem/group/tool\")\n  const tool = discovery.describe(\"ai/filesystem/group/tool\") as {description: string; views: string[]}\n  assert.equal(tool.description, \"Safe description.\")\n  assert.deepEqual(tool.views, [\"overview\"])\n}))\ntest(\"manifests have no runtime dependency on Interpreter, UI, browser or Storybook\", () => {\n  for (const path of [\"package.json\", \"filesystem/package.json\", \"git/package.json\", \"server/package.json\"]) {\n    const manifest = JSON.parse(readFileSync(join(repositoryRoot, path), \"utf8\"))\n    assert.equal(manifest.dependencies, undefined)\n  }\n})\n",
  "server/discovery/src/read.ts": "import {lstatSync, openSync, closeSync, readSync, constants, realpathSync} from \"node:fs\"\nimport {dirname, relative, resolve, sep, isAbsolute} from \"node:path\"\nimport {ToolError} from \"../../../shared/errors.ts\"\n\nexport function source(root: string, name: string, optional = false): string | null {\n  const path = resolve(root, name)\n  const relation = relative(root, path)\n  if (relation === \"..\" || relation.startsWith(`..${sep}`) || isAbsolute(relation)) throw new ToolError(\"INVALID_STRUCTURE\", \"Source path escapes the repository\", 500)\n  let stat\n  try { stat = lstatSync(path) } catch (error) {\n    if (optional && (error as NodeJS.ErrnoException).code === \"ENOENT\") return null\n    throw error\n  }\n  if (!stat.isFile() || stat.isSymbolicLink() || realpathSync(dirname(path)) !== dirname(path)) throw new ToolError(\"INVALID_STRUCTURE\", \"Metadata must be a regular file without symlink parents\", 500)\n  if (stat.size > 131072) throw new ToolError(\"LIMIT_EXCEEDED\", \"Metadata source exceeds 128 KiB\", 413)\n  const fd = openSync(path, constants.O_RDONLY | constants.O_NOFOLLOW)\n  try {\n    const buffer = Buffer.alloc(stat.size)\n    const bytes = readSync(fd, buffer, 0, buffer.length, 0)\n    if (bytes !== stat.size) throw new ToolError(\"CONFLICT\", \"Metadata source changed while reading\", 409)\n    return buffer.toString(\"utf8\")\n  } finally { closeSync(fd) }\n}\n\nexport function overview(text: string | null): string | null {\n  const block = text?.match(/^\\s*\\/\\*\\*([\\s\\S]*?)\\*\\//)?.[1]\n  if (!block?.includes(\"@packageDocumentation\")) return null\n  return block.replace(/^\\s*\\* ?/gm, \"\").replace(\"@packageDocumentation\", \"\").trim()\n}\n",
  "server/dispatch/contract/input.ts": "/** JSON envelope shared by an embedded lazy MCP host and the optional HTTP adapter. */\nexport interface ToolRequest {\n  node?: string\n  action?: \"run\"\n  input?: Record<string, unknown>\n}\n\nexport interface ToolInvocation {\n  readonly node: string\n  /** Detached, deeply frozen arguments. Not a mutable reference to the caller's request. */\n  readonly input: Readonly<Record<string, unknown>>\n  /** Absolute lexical targets; this list does not assert existence or permission. */\n  readonly paths: readonly string[]\n  readonly effect: \"read\" | \"write\"\n}\n\n/** Host dependencies, never fields in a remote request. */\nexport interface DispatcherInput {\n  /** Проверяется непосредственно перед синхронным исполнением. */\n  signal?: AbortSignal\n  /** Доверенный источник упакованных текстовых метаданных. */\n  readSource?: (name: string, optional?: boolean) => string | null\n\n  /** Trusted source tree for lazy descriptions, not an execution workspace. */\n  repositoryRoot: string\n  /** Must return true for each run. Missing, false, undefined or thrown approval never executes a tool. */\n  authorize?: (invocation: ToolInvocation) => boolean | Promise<boolean>\n}\n",
  "server/dispatch/contract/output.ts": "import type {ToolRequest} from \"./input.ts\"\n\n/** No listener, session, process launcher, retries or MCP registration. */\nexport interface DispatcherOutput {\n  /** Returns the public function's result; errors propagate to the calling host. */\n  dispatch(request?: ToolRequest): Promise<unknown>\n}\n",
  "server/dispatch/index.ts": "/**\n * Общий lazy-вход для встраивания в существующий Завхоз и для HTTP-адаптера.\n * @remarks Описание ничего не исполняет. run требует явного разрешения хоста.\n * Не запускает сервер, MCP, Interpreter, браузер или второй Runtime.\n * @packageDocumentation\n */\nimport {ToolError} from \"../../shared/errors.ts\"\nimport {object, text} from \"../../shared/validation.ts\"\nimport {absolutePath} from \"../../filesystem/shared/paths.ts\"\nimport {createDiscovery} from \"../discovery/index.ts\"\nimport {bindings} from \"./src/bindings.ts\"\nimport type {DispatcherInput, ToolRequest, ToolInvocation} from \"./contract/input.ts\"\nimport type {DispatcherOutput} from \"./contract/output.ts\"\nexport type {DispatcherInput, ToolRequest, ToolInvocation} from \"./contract/input.ts\"\nexport type {DispatcherOutput} from \"./contract/output.ts\"\n\nfunction frozen<T>(value: T, seen = new WeakSet<object>()): T {\n  if (value !== null && typeof value === \"object\" && !seen.has(value)) {\n    seen.add(value)\n    for (const child of Object.values(value)) frozen(child, seen)\n    Object.freeze(value)\n  }\n  return value\n}\n\nexport function createDispatcher(options: DispatcherInput): DispatcherOutput {\n  const handlers = bindings()\n  const discovery = createDiscovery({repositoryRoot: options.repositoryRoot, readSource: options.readSource, runnable: new Set(handlers.keys())})\n  // The authority is supplied by the host, not selected or replaced in a tool request.\n  const authorize = options.authorize\n  return {dispatch: async (request: ToolRequest = {}) => {\n    options.signal?.throwIfAborted()\n    object(request, [\"node\", \"action\", \"input\"])\n    const node = request.node === undefined ? undefined : text(request.node, \"node\")\n    const action = request.action === undefined ? undefined : text(request.action, \"action\")\n    if (action === undefined) {\n      const input = request.input ?? {}\n      object(input, [\"view\"])\n      return discovery.describe(node, input[\"view\"] === undefined ? undefined : text(input[\"view\"], \"view\"))\n    }\n    if (action !== \"run\") throw new ToolError(\"ACTION_NOT_ALLOWED\", \"Only action: run executes tools\")\n    if (node === undefined || !discovery.has(node)) throw new ToolError(\"UNKNOWN_NODE\", \"Unknown executable node\", 404)\n    const handler = handlers.get(node)\n    if (handler === undefined) throw new ToolError(\"ACTION_NOT_ALLOWED\", \"This structural node is not executable\", 403)\n    if (authorize === undefined) throw new ToolError(\"AUTHORIZATION_REQUIRED\", \"The calling host must authorize tool execution\", 403)\n    const supplied = request.input ?? {}\n    object(supplied, Object.keys(supplied))\n    let input: Readonly<Record<string, unknown>>\n    try { input = frozen(structuredClone(supplied)) }\n    catch { throw new ToolError(\"INVALID_INPUT\", \"Arguments must be structured-cloneable data\") }\n    const paths = handler.fields.flatMap(field => {\n      const value = input[field]\n      if (field !== \"paths\") return [absolutePath(value)]\n      if (!Array.isArray(value) || value.length === 0 || value.length > 50) throw new ToolError(\"INVALID_INPUT\", \"paths must contain 1 to 50 strings\")\n      return value.map(absolutePath)\n    })\n    const effect = handler.write && !(node === \"ai/filesystem/apply-patch\" && input[\"dryRun\"] === true) ? \"write\" : \"read\"\n    const invocation: ToolInvocation = Object.freeze({node, input, paths: Object.freeze(paths), effect})\n    if (await authorize(invocation) !== true) throw new ToolError(\"AUTHORIZATION_REQUIRED\", \"The calling host did not authorize this invocation\", 403)\n    options.signal?.throwIfAborted()\n    return handler.run(input)\n  }}\n}\n",
  "server/dispatch/spec/scenario.spec.ts": "import {test} from \"node:test\"\nimport assert from \"node:assert/strict\"\nimport {existsSync, readFileSync, writeFileSync} from \"node:fs\"\nimport {join} from \"node:path\"\nimport {createDispatcher} from \"../index.ts\"\nimport type {ToolInvocation} from \"../contract/input.ts\"\nimport {fixture, hasCode} from \"../../../filesystem/shared/spec-fixture.ts\"\nimport {repositoryRoot} from \"../../request/spec/fixture.ts\"\n\nconst create = (path: string) => ({node: \"ai/filesystem/create\", action: \"run\" as const, input: {path, content: \"new\"}})\n\ntest(\"embedded discovery never needs approval and never executes\", () => fixture(async directory => {\n  let calls = 0\n  const app = createDispatcher({repositoryRoot, authorize: () => {calls++; return true}})\n  const overview = await app.dispatch({node: \"ai/filesystem/create\"}) as {runnable: boolean}\n  assert.equal(overview.runnable, true)\n  const contract = await app.dispatch({node: \"ai/filesystem/create\", input: {view: \"contract\"}}) as {input: string}\n  assert.match(contract.input, /path: string/)\n  assert.doesNotMatch(contract.input, /root:/)\n  const scenario = await app.dispatch({node: \"ai/filesystem/create\", input: {view: \"scenarios\"}}) as {executed: boolean}\n  assert.equal(scenario.executed, false)\n  assert.equal(calls, 0)\n  assert.equal(existsSync(join(directory, \"file\")), false)\n}))\ntest(\"embedded execution is denied by default, not implied by discovery\", () => fixture(async directory => {\n  const app = createDispatcher({repositoryRoot})\n  await app.dispatch({node: \"ai/filesystem/create\"})\n  await assert.rejects(app.dispatch(create(join(directory, \"file\"))), hasCode(\"AUTHORIZATION_REQUIRED\"))\n  assert.equal(existsSync(join(directory, \"file\")), false)\n}))\ntest(\"false, undefined and failed host approval never execute\", () => fixture(async directory => {\n  for (const authorize of [() => false, () => undefined, () => {throw new Error(\"policy unavailable\")}]) {\n    const app = createDispatcher({repositoryRoot, authorize: authorize as never})\n    await assert.rejects(app.dispatch(create(join(directory, \"file\"))))\n    assert.equal(existsSync(join(directory, \"file\")), false)\n  }\n}))\ntest(\"embedded execution uses direct tool input and returns the public result\", () => fixture(async directory => {\n  const path = join(directory, \"file\")\n  const invocations: ToolInvocation[] = []\n  const app = createDispatcher({repositoryRoot, authorize: invocation => {invocations.push(invocation); return true}})\n  await app.dispatch(create(path))\n  const result = await app.dispatch({node: \"ai/filesystem/read\", action: \"run\", input: {path}}) as {path: string; content: string}\n  assert.equal(result.path, path)\n  assert.equal(result.content, \"new\")\n  assert.deepEqual(invocations.map(item => item.effect), [\"write\", \"read\"])\n  assert.deepEqual(invocations[0]!.paths, [path])\n}))\ntest(\"arguments cannot change while asynchronous approval is pending\", () => fixture(async directory => {\n  const first = join(directory, \"approved\")\n  const other = join(directory, \"not-approved\")\n  const request = create(first)\n  let entered!: () => void\n  const pending = new Promise<void>(done => {entered = done})\n  let release!: (value: boolean) => void\n  const approval = new Promise<boolean>(done => {release = done})\n  const app = createDispatcher({repositoryRoot, authorize: invocation => {\n    assert.equal(Object.isFrozen(invocation), true)\n    assert.equal(Object.isFrozen(invocation.input), true)\n    assert.equal(Object.isFrozen(invocation.paths), true)\n    assert.throws(() => { (invocation.input as Record<string, unknown>)[\"path\"] = other }, TypeError)\n    entered()\n    return approval\n  }})\n  const result = app.dispatch(request)\n  await pending\n  request.input.path = other\n  request.input.content = \"changed\"\n  release(true)\n  await result\n  assert.equal(readFileSync(first, \"utf8\"), \"new\")\n  assert.equal(existsSync(other), false)\n}))\ntest(\"read-many arrays are detached and deeply frozen during approval\", () => fixture(async directory => {\n  const path = join(directory, \"file\")\n  writeFileSync(path, \"ok\")\n  const paths = [path]\n  const app = createDispatcher({repositoryRoot, authorize: invocation => {\n    assert.equal(Object.isFrozen(invocation.input[\"paths\"]), true)\n    paths[0] = join(directory, \"missing\")\n    return true\n  }})\n  const result = await app.dispatch({node: \"ai/filesystem/read-many\", action: \"run\", input: {paths}}) as {files: {result: {content: string}}[]}\n  assert.equal(result.files[0]!.result.content, \"ok\")\n}))\ntest(\"patch dryRun is classified as read and creates no directory\", () => fixture(async directory => {\n  let effect: string | undefined\n  const app = createDispatcher({repositoryRoot, authorize: invocation => {effect = invocation.effect; return true}})\n  await app.dispatch({node: \"ai/filesystem/apply-patch\", action: \"run\", input: {\n    directory, dryRun: true, patch: \"*** Begin Patch\\n*** Add File: new/file\\n+x\\n*** End Patch\",\n  }})\n  assert.equal(effect, \"read\")\n  assert.equal(existsSync(join(directory, \"new\")), false)\n}))\ntest(\"removed tools and arbitrary executable nodes are rejected\", async () => {\n  const app = createDispatcher({repositoryRoot, authorize: () => true})\n  for (const node of [\"ai/filesystem/roots\", \"ai/filesystem/open\", \"../../etc/passwd\"]) {\n    await assert.rejects(app.dispatch({node}), hasCode(\"UNKNOWN_NODE\"))\n    await assert.rejects(app.dispatch({node, action: \"run\"}), hasCode(\"UNKNOWN_NODE\"))\n  }\n  await assert.rejects(app.dispatch({node: \"ai/server/dispatch\", action: \"run\"}), hasCode(\"ACTION_NOT_ALLOWED\"))\n})\ntest(\"request cannot supply authority or override the explicit run action\", () => fixture(async directory => {\n  const app = createDispatcher({repositoryRoot, authorize: () => true})\n  await assert.rejects(app.dispatch({...create(join(directory, \"file\")), authorize: true} as never), hasCode(\"INVALID_INPUT\"))\n  await assert.rejects(app.dispatch({...create(join(directory, \"file\")), action: \"execute\"} as never), hasCode(\"ACTION_NOT_ALLOWED\"))\n  await assert.rejects(app.dispatch({...create(join(directory, \"file\")), input: {path: join(directory, \"file\"), root: \"repo\", content: \"x\"}}), hasCode(\"INVALID_INPUT\"))\n  assert.equal(existsSync(join(directory, \"file\")), false)\n}))\n",
  "server/dispatch/src/bindings.ts": "import {statPath} from \"../../../filesystem/stat/index.ts\"\nimport {readFile} from \"../../../filesystem/read/index.ts\"\nimport {readFiles} from \"../../../filesystem/read-many/index.ts\"\nimport {listFiles} from \"../../../filesystem/list/index.ts\"\nimport {writeFile} from \"../../../filesystem/write/index.ts\"\nimport {createFile} from \"../../../filesystem/create/index.ts\"\nimport {makeDirectory} from \"../../../filesystem/mkdir/index.ts\"\nimport {removePath} from \"../../../filesystem/remove/index.ts\"\nimport {renamePath} from \"../../../filesystem/rename/index.ts\"\nimport {applyPatch} from \"../../../filesystem/apply-patch/index.ts\"\nimport {gitStatus} from \"../../../git/status/index.ts\"\n\ninterface Binding {\n  run(input: unknown): unknown\n  fields: readonly string[]\n  write: boolean\n}\nfunction bind<I>(run: (input: I) => unknown, fields: readonly string[], write = false): Binding {\n  return {run: input => run(input as I), fields, write}\n}\n\n/** Fixed public functions, not a second schema catalogue or dynamic imports. */\nexport function bindings(): ReadonlyMap<string, Binding> {\n  return new Map([\n    [\"ai/filesystem/stat\", bind(statPath, [\"path\"])],\n    [\"ai/filesystem/read\", bind(readFile, [\"path\"])],\n    [\"ai/filesystem/read-many\", bind(readFiles, [\"paths\"])],\n    [\"ai/filesystem/list\", bind(listFiles, [\"path\"])],\n    [\"ai/filesystem/write\", bind(writeFile, [\"path\"], true)],\n    [\"ai/filesystem/create\", bind(createFile, [\"path\"], true)],\n    [\"ai/filesystem/mkdir\", bind(makeDirectory, [\"path\"], true)],\n    [\"ai/filesystem/remove\", bind(removePath, [\"path\"], true)],\n    [\"ai/filesystem/rename\", bind(renamePath, [\"from\", \"to\"], true)],\n    [\"ai/filesystem/apply-patch\", bind(applyPatch, [\"directory\"], true)],\n    [\"ai/git/status\", bind(gitStatus, [\"path\"])],\n  ])\n}\n",
  "server/index.ts": "/**\n * Запускает необязательный HTTP-host универсальных инструментов.\n * @remarks Для встраивания в Завхоз импортируют server/dispatch, а не запускают\n * этот listener. Никаких Interpreter, браузера или отдельного MCP-server.\n * @packageDocumentation\n */\nimport {createServer} from \"node:http\"\nimport {Readable} from \"node:stream\"\nimport {fileURLToPath} from \"node:url\"\nimport {dirname, resolve} from \"node:path\"\nimport type {AddressInfo} from \"node:net\"\nimport {integer, text, boolean} from \"../shared/validation.ts\"\nimport {createRequestHandler} from \"./request/index.ts\"\nimport {directoryAuthorizer} from \"./request/src/authorize.ts\"\nimport type {ServerInput} from \"./contract/input.ts\"\nimport type {ServerOutput} from \"./contract/output.ts\"\nexport type {ServerInput} from \"./contract/input.ts\"\nexport type {ServerOutput} from \"./contract/output.ts\"\n\nexport async function startServer(options: ServerInput): Promise<ServerOutput> {\n  const authorize = directoryAuthorizer(options.allowedDirectories)\n  const hostname = text(options.hostname ?? \"127.0.0.1\", \"hostname\")\n  const port = integer(options.port, 8787, 0, 65535, \"port\")\n  const log = boolean(options.log, true, \"log\")\n  const handler = createRequestHandler({authorize, token: options.token,\n    repositoryRoot: options.repositoryRoot ?? resolve(dirname(fileURLToPath(import.meta.url)), \"..\"),\n    logger: log ? event => process.stderr.write(JSON.stringify(event) + \"\\n\") : undefined})\n  const server = createServer(async (incoming, outgoing) => {\n    try {\n      const method = incoming.method ?? \"GET\"\n      const headers = new Headers()\n      for (const [name, value] of Object.entries(incoming.headers)) if (value !== undefined) headers.set(name, Array.isArray(value) ? value.join(\", \") : value)\n      const init: RequestInit & {duplex?: \"half\"} = {method, headers}\n      if (method !== \"GET\" && method !== \"HEAD\") {\n        init.body = Readable.toWeb(incoming) as ReadableStream<Uint8Array>\n        init.duplex = \"half\"\n      }\n      const response = await handler.handle(new Request(`http://localhost${incoming.url ?? \"/\"}`, init))\n      outgoing.writeHead(response.status, Object.fromEntries(response.headers.entries()))\n      outgoing.end(Buffer.from(await response.arrayBuffer()))\n    } catch {\n      if (!outgoing.headersSent) outgoing.writeHead(400, {\"content-type\": \"application/json\", \"cache-control\": \"no-store\"})\n      outgoing.end(JSON.stringify({error: {code: \"INVALID_REQUEST\", message: \"Could not process HTTP request\"}}))\n    }\n  })\n  await new Promise<void>((done, reject) => {\n    server.once(\"error\", reject)\n    server.listen(port, hostname, () => {server.off(\"error\", reject); done()})\n  })\n  const address = server.address() as AddressInfo\n  const host = address.family === \"IPv6\" ? `[${address.address}]` : address.address\n  return {url: `http://${host}:${address.port}/tools`, close: () => new Promise<void>((done, reject) => server.close(error => error ? reject(error) : done()))}\n}\n\nif (process.argv[1] !== undefined && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {\n  try {\n    const allowedDirectories = JSON.parse(process.env[\"AI_TOOLS_ALLOWED_DIRECTORIES\"] ?? \"null\") as string[]\n    const host = await startServer({allowedDirectories, token: process.env[\"AI_TOOLS_TOKEN\"] ?? \"\",\n      hostname: process.env[\"AI_TOOLS_HOST\"], port: process.env[\"AI_TOOLS_PORT\"] === undefined ? undefined : Number(process.env[\"AI_TOOLS_PORT\"])})\n    process.stderr.write(`AI tools listening at ${host.url}\\n`)\n    const stop = (): void => { void host.close().catch(() => {process.exitCode = 1}) }\n    process.once(\"SIGINT\", stop)\n    process.once(\"SIGTERM\", stop)\n  } catch (error) {\n    process.stderr.write(`Unable to start AI tools: ${error instanceof Error ? error.message : \"invalid configuration\"}\\n`)\n    process.exitCode = 1\n  }\n}\n",
  "server/package.json": "{\n  \"name\": \"@ai/server\",\n  \"label\": \"Tool Host\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"exports\": {\n    \".\": \"./index.ts\",\n    \"./dispatch\": \"./dispatch/index.ts\",\n    \"./request\": \"./request/index.ts\",\n    \"./discovery\": \"./discovery/index.ts\"\n  }\n}\n",
  "server/README.md": "# Tool Host\n\nКомпозиция универсальных инструментов; не новый предметный runtime.\n\n- dispatch — общий встраиваемый lazy-вход с обязательным разрешением выполнения.\n- discovery — чтение package identity, exports, исходных контрактов и сценариев.\n- request — HTTP-адаптер той же функции dispatch; index.ts — необязательный listener.\n\nJSON-оболочка: {node?, action?, input?}. Без action — описание, единственное\nисполняющее действие — run. Нет версии URL или собственного MCP SDK.\nТермин: lazy MCP. Не существует зависимости от стороннего SDK с созвучным названием.\n\nserver/dispatch/src/bindings.ts содержит явные ссылки на 11 публичных функций.\nЭто не второй каталог контрактов. exports сами по себе не дают права исполнения.\nТехнические узлы сервера нельзя запускать удалённо. Импорт dispatch не открывает\nсокет, не запускает процесс, не читает пользовательские файлы и не регистрирует MCP.\nСоздание dispatcher читает только доверенные метаданные из repositoryRoot.\n\nauthorize передаёт хост при создании dispatcher, не клиент в запросе. До выполнения\nхост получает node, неизменяемую копию input, абсолютные targets в paths и effect.\nДля patch это директория применения; содержимое патча доступно в input для более\nстрогой политики хоста. paths — не доказательство существования или допуска.\nБез явного true выполнение закрыто. Аргументы заморожены до асинхронного ожидания.\n\nHTTP-host использует собственную приватную политику allowedDirectories без aliases.\nОна проверяет физические родительские пути, обе стороны rename и запрещает удаление\nили переименование самой разрешённой директории. Отсутствующая конфигурация — ошибка,\nа не доступ ко всей машине. Это не OS sandbox и не межпроцессная блокировка путей.\n\nBearer обязателен даже для discovery. Origin-запросы из браузера не разрешены.\nТело ограничено 12 MiB; нет произвольного import или shell и повторов после обрыва.\nrequestId связывает ответ с JSONL-диагностикой без input, содержимого и токенов.\nСбой логирования не меняет результат уже выполненной операции.\n\nСценарии находятся в dispatch/spec, discovery/spec и request/spec. Реальный\nloopback HTTP-прогон использует случайный порт и собственную временную директорию.\nИнтеграция с текущим ServiceClient Завхоза ещё требует адаптера; см. ../INTEGRATION.md.\n",
  "server/request/contract/input.ts": "import type {DispatcherInput} from \"../../dispatch/contract/input.ts\"\n\n/** Trusted HTTP-host dependencies; these fields never come from a remote tool call. */\nexport interface RequestInput extends DispatcherInput {\n  token: string\n  logger?: (event: {requestId: string; method: string; node?: string; action?: string; status: number; durationMs: number; errorCode?: string}) => void\n}\n",
  "server/request/contract/output.ts": "export interface RequestOutput {\n  handle(request: Request): Promise<Response>\n}\n",
  "server/request/index.ts": "/**\n * Необязательный HTTP-адаптер lazy MCP: GET /tools и POST /tools.\n * @remarks Все запросы требуют Bearer token. Выполнение делегируется тому же\n * createDispatcher, что используется при встраивании, без второго исполнителя.\n * @packageDocumentation\n */\nimport {randomUUID, timingSafeEqual} from \"node:crypto\"\nimport {ToolError, asToolError} from \"../../shared/errors.ts\"\nimport {object, text} from \"../../shared/validation.ts\"\nimport {createDispatcher} from \"../dispatch/index.ts\"\nimport type {ToolRequest} from \"../dispatch/contract/input.ts\"\nimport {readBody} from \"./src/body.ts\"\nimport type {RequestInput} from \"./contract/input.ts\"\nimport type {RequestOutput} from \"./contract/output.ts\"\nexport type {RequestInput} from \"./contract/input.ts\"\nexport type {RequestOutput} from \"./contract/output.ts\"\n\nexport function createRequestHandler(options: RequestInput): RequestOutput {\n  const token = text(options.token, \"token\")\n  if (token.length < 32 || token.length > 256) throw new ToolError(\"INVALID_INPUT\", \"Token must contain 32 to 256 characters\")\n  const expected = Buffer.from(`Bearer ${token}`)\n  const dispatcher = createDispatcher(options)\n  return {handle: async request => {\n    const requestId = randomUUID()\n    const started = performance.now()\n    let node: string | undefined\n    let action: string | undefined\n    let status = 200\n    let errorCode: string | undefined\n    let data: unknown\n    try {\n      const provided = Buffer.from(request.headers.get(\"authorization\") ?? \"\")\n      if (provided.length !== expected.length || !timingSafeEqual(provided, expected)) throw new ToolError(\"UNAUTHORIZED\", \"A valid Bearer token is required\", 401)\n      if (request.headers.has(\"origin\")) throw new ToolError(\"ORIGIN_NOT_ALLOWED\", \"Browser-origin requests are not enabled\", 403)\n      const url = new URL(request.url)\n      if (url.pathname !== \"/tools\") throw new ToolError(\"NOT_FOUND\", \"Unknown endpoint\", 404)\n      if (url.search !== \"\") throw new ToolError(\"INVALID_INPUT\", \"Use the JSON request body, not URL query parameters\")\n      if (request.method !== \"GET\" && request.method !== \"POST\") throw new ToolError(\"METHOD_NOT_ALLOWED\", \"Use GET or POST\", 405)\n      const payload = request.method === \"GET\" ? {} : await readBody(request)\n      object(payload, [\"node\", \"action\", \"input\"])\n      const body = payload as ToolRequest\n      node = body.node === undefined ? undefined : text(body.node, \"node\")\n      action = body.action === undefined ? undefined : text(body.action, \"action\")\n      data = await dispatcher.dispatch(body)\n    } catch (error) {\n      const failure = asToolError(error)\n      status = failure.status\n      errorCode = failure.code\n      data = {error: {code: failure.code, message: failure.message, ...(failure.details === undefined ? {} : {details: failure.details})}, requestId}\n    }\n    const headers: Record<string, string> = {\"content-type\": \"application/json; charset=utf-8\", \"cache-control\": \"no-store\", \"x-content-type-options\": \"nosniff\", \"x-request-id\": requestId}\n    if (status === 401) headers[\"www-authenticate\"] = \"Bearer\"\n    if (status === 405) headers[\"allow\"] = \"GET, POST\"\n    try { options.logger?.({requestId, method: request.method, node, action, status, durationMs: Math.round(performance.now() - started), errorCode}) }\n    catch { /* Diagnostics must not change an already completed operation. */ }\n    return new Response(JSON.stringify(data), {status, headers})\n  }}\n}\n",
  "server/request/spec/fixture.ts": "import {dirname, resolve} from \"node:path\"\nimport {fileURLToPath} from \"node:url\"\nexport const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), \"../../..\")\nexport const token = \"test-token-not-a-real-secret-1234567890\"\nexport function post(body: unknown, headers: Record<string, string> = {}): Request {\n  return new Request(\"http://localhost/tools\", {method: \"POST\", headers: {authorization: `Bearer ${token}`, \"content-type\": \"application/json\", ...headers}, body: JSON.stringify(body)})\n}\n",
  "server/request/spec/scenario.spec.ts": "import {test} from \"node:test\"\nimport assert from \"node:assert/strict\"\nimport {writeFileSync, readFileSync, existsSync, symlinkSync} from \"node:fs\"\nimport {join} from \"node:path\"\nimport {createRequestHandler} from \"../index.ts\"\nimport {directoryAuthorizer} from \"../src/authorize.ts\"\nimport {startServer} from \"../../index.ts\"\nimport {fixture, hasCode} from \"../../../filesystem/shared/spec-fixture.ts\"\nimport {repositoryRoot, token, post} from \"./fixture.ts\"\n\nconst appFor = (directory: string) => createRequestHandler({authorize: directoryAuthorizer([directory]), token, repositoryRoot})\nconst run = (name: string, input: Record<string, unknown>) => post({node: `ai/filesystem/${name}`, action: \"run\", input})\n\ntest(\"HTTP GET and empty POST discover the same root\", () => fixture(async directory => {\n  const app = appFor(directory)\n  const get = await app.handle(new Request(\"http://localhost/tools\", {headers: {authorization: `Bearer ${token}`}}))\n  const empty = await app.handle(post({}))\n  assert.equal(get.status, 200)\n  assert.deepEqual(await get.json(), await empty.json())\n}))\ntest(\"HTTP requires a token even for discovery\", () => fixture(async directory => {\n  const response = await appFor(directory).handle(new Request(\"http://localhost/tools\"))\n  assert.equal(response.status, 401)\n  assert.equal(response.headers.get(\"www-authenticate\"), \"Bearer\")\n  assert.equal((await response.json()).error.code, \"UNAUTHORIZED\")\n}))\ntest(\"HTTP discovers contracts and scenarios without executing\", () => fixture(async directory => {\n  const path = join(directory, \"file\")\n  writeFileSync(path, \"unchanged\")\n  const app = appFor(directory)\n  assert.equal((await (await app.handle(post({node: \"ai/filesystem/write\"}))).json()).runnable, true)\n  const contract = await app.handle(post({node: \"ai/filesystem/write\", input: {view: \"contract\"}}))\n  assert.match((await contract.json()).input, /expectedHash/)\n  const scenario = await app.handle(post({node: \"ai/filesystem/write\", input: {view: \"scenarios\"}}))\n  assert.equal((await scenario.json()).executed, false)\n  assert.equal(readFileSync(path, \"utf8\"), \"unchanged\")\n}))\ntest(\"HTTP executes the real public function with an absolute path\", () => fixture(async directory => {\n  const path = join(directory, \"file\")\n  writeFileSync(path, \"hello\")\n  const response = await appFor(directory).handle(run(\"read\", {path}))\n  assert.equal(response.status, 200)\n  assert.equal((await response.json()).content, \"hello\")\n}))\ntest(\"HTTP rejects imports, technical nodes, removed tools and invalid envelopes\", () => fixture(async directory => {\n  const app = appFor(directory)\n  for (const [body, status] of [\n    [{node: \"../../etc/passwd\", action: \"run\"}, 404],\n    [{node: \"ai/server/request\", action: \"run\"}, 403],\n    [{node: \"ai/server/dispatch\", action: \"run\"}, 403],\n    [{node: \"ai/filesystem/roots\"}, 404],\n    [{node: \"ai/filesystem/open\", action: \"run\"}, 404],\n    [{node: \"ai/filesystem/read\", action: \"execute\"}, 400],\n    [{node: \"ai/filesystem/read\", input: {path: join(directory, \"file\")}}, 400],\n    [{node: \"ai/filesystem/read\", action: \"run\", input: []}, 400],\n    [{extra: true}, 400], [[], 400],\n  ] as const) assert.equal((await app.handle(post(body))).status, status)\n}))\ntest(\"HTTP distinguishes missing paths, conflicts and denied directories\", () => fixture(async directory => fixture(async outside => {\n  const path = join(directory, \"existing\")\n  writeFileSync(path, \"old\")\n  const app = appFor(directory)\n  assert.equal((await app.handle(run(\"read\", {path: join(directory, \"missing\")}))).status, 404)\n  assert.equal((await app.handle(run(\"create\", {path, content: \"new\"}))).status, 409)\n  const denied = await app.handle(run(\"create\", {path: join(outside, \"private\"), content: \"bad\"}))\n  assert.equal(denied.status, 403)\n  assert.equal(existsSync(join(outside, \"private\")), false)\n  assert.equal(readFileSync(path, \"utf8\"), \"old\")\n})))\ntest(\"HTTP rejects unsupported methods, media types and browser origins\", () => fixture(async directory => {\n  const app = appFor(directory)\n  assert.equal((await app.handle(new Request(\"http://localhost/tools\", {method: \"DELETE\", headers: {authorization: `Bearer ${token}`}}))).status, 405)\n  assert.equal((await app.handle(post({}, {\"content-type\": \"text/plain\"}))).status, 415)\n  assert.equal((await app.handle(post({}, {origin: \"https://untrusted.invalid\"}))).status, 403)\n  assert.equal((await app.handle(new Request(\"http://localhost/v1/tools\", {headers: {authorization: `Bearer ${token}`}}))).status, 404)\n}))\ntest(\"HTTP rejects malformed JSON and oversized bodies\", () => fixture(async directory => {\n  const app = appFor(directory)\n  const invalid = new Request(\"http://localhost/tools\", {method: \"POST\", headers: {authorization: `Bearer ${token}`, \"content-type\": \"application/json\"}, body: \"{\"})\n  assert.equal((await app.handle(invalid)).status, 400)\n  assert.equal((await app.handle(post({}, {\"content-length\": \"13000000\"}))).status, 413)\n  const large = new Request(\"http://localhost/tools\", {method: \"POST\", headers: {authorization: `Bearer ${token}`, \"content-type\": \"application/json\"}, body: \"x\".repeat(12 * 1024 * 1024 + 1)})\n  assert.equal((await app.handle(large)).status, 413)\n}))\ntest(\"HTTP logs operation metadata, not file contents or credentials\", () => fixture(async directory => {\n  const logs: unknown[] = []\n  const app = createRequestHandler({authorize: directoryAuthorizer([directory]), token, repositoryRoot, logger: event => logs.push(event)})\n  const response = await app.handle(run(\"create\", {path: join(directory, \"file\"), content: \"private-content-marker\"}))\n  assert.equal(response.status, 200)\n  const encoded = JSON.stringify(logs)\n  assert.equal(encoded.includes(token), false)\n  assert.equal(encoded.includes(\"private-content-marker\"), false)\n  assert.ok(encoded.includes(response.headers.get(\"x-request-id\")!))\n}))\ntest(\"diagnostics failure does not invalidate a completed write\", () => fixture(async directory => {\n  const app = createRequestHandler({authorize: directoryAuthorizer([directory]), token, repositoryRoot, logger: () => {throw new Error(\"logger unavailable\")}})\n  const path = join(directory, \"file\")\n  assert.equal((await app.handle(run(\"create\", {path, content: \"ok\"}))).status, 200)\n  assert.equal(readFileSync(path, \"utf8\"), \"ok\")\n}))\ntest(\"HTTP construction rejects a weak token\", () => {\n  assert.throws(() => createRequestHandler({token: \"short\", repositoryRoot}), hasCode(\"INVALID_INPUT\"))\n})\ntest(\"real loopback listener reads through the same tools without Interpreter\", () => fixture(async directory => {\n  const path = join(directory, \"file\")\n  writeFileSync(path, \"network\")\n  const host = await startServer({allowedDirectories: [directory], token, repositoryRoot, port: 0, log: false})\n  try {\n    const response = await fetch(host.url, {method: \"POST\", headers: {authorization: `Bearer ${token}`, \"content-type\": \"application/json\"},\n      body: JSON.stringify({node: \"ai/filesystem/read\", action: \"run\", input: {path}})})\n    assert.equal(response.status, 200)\n    assert.equal((await response.json()).content, \"network\")\n  } finally { await host.close() }\n}))\ntest(\"valid Bearer token alone cannot bypass absent execution authority\", () => fixture(async directory => {\n  const path = join(directory, \"file\")\n  const app = createRequestHandler({token, repositoryRoot})\n  const response = await app.handle(run(\"create\", {path, content: \"bad\"}))\n  assert.equal(response.status, 403)\n  assert.equal((await response.json()).error.code, \"AUTHORIZATION_REQUIRED\")\n  assert.equal(existsSync(path), false)\n}))\ntest(\"HTTP policy checks physical parent paths and both rename endpoints\", () => fixture(async directory => fixture(async outside => {\n  symlinkSync(outside, join(directory, \"escape\"))\n  const app = appFor(directory)\n  assert.equal((await app.handle(run(\"create\", {path: join(directory, \"escape/file\"), content: \"bad\"}))).status, 403)\n  const from = join(directory, \"from\")\n  const to = join(outside, \"to\")\n  writeFileSync(from, \"safe\")\n  assert.equal((await app.handle(run(\"rename\", {from, to}))).status, 403)\n  assert.equal(readFileSync(from, \"utf8\"), \"safe\")\n  assert.equal(existsSync(to), false)\n  assert.equal(existsSync(join(outside, \"file\")), false)\n})))\ntest(\"HTTP policy protects its configured directory entry\", () => fixture(async directory => {\n  const app = appFor(directory)\n  assert.equal((await app.handle(run(\"remove\", {path: directory, recursive: true}))).status, 403)\n  assert.equal((await app.handle(run(\"rename\", {from: directory, to: directory + \"-new\"}))).status, 403)\n  assert.equal(existsSync(directory), true)\n}))\ntest(\"HTTP patch may use a permitted directory without registration calls\", () => fixture(async directory => {\n  const response = await appFor(directory).handle(run(\"apply-patch\", {directory, patch: \"*** Begin Patch\\n*** Add File: file\\n+ok\\n*** End Patch\"}))\n  assert.equal(response.status, 200)\n  assert.equal(readFileSync(join(directory, \"file\"), \"utf8\"), \"ok\\n\")\n}))\ntest(\"server rejects absent permissions and legacy root config before listening\", () => fixture(async directory => {\n  await assert.rejects(startServer({token, repositoryRoot, port: 0} as never), hasCode(\"INVALID_INPUT\"))\n  await assert.rejects(startServer({roots: {repo: directory}, token, repositoryRoot, port: 0} as never), hasCode(\"INVALID_INPUT\"))\n  assert.throws(() => directoryAuthorizer([]), hasCode(\"INVALID_INPUT\"))\n}))\n",
  "server/request/src/authorize.ts": "import {lstatSync, realpathSync} from \"node:fs\"\nimport {ToolError} from \"../../../shared/errors.ts\"\nimport {resolvePath, within} from \"../../../filesystem/shared/paths.ts\"\nimport type {ToolInvocation} from \"../../dispatch/contract/input.ts\"\n\n/** Optional HTTP host policy. It is not part of any tool input or function dependency. */\nexport function directoryAuthorizer(values: string[]): (invocation: ToolInvocation) => boolean {\n  if (!Array.isArray(values) || values.length === 0 || values.length > 64) throw new ToolError(\"INVALID_INPUT\", \"Configure 1 to 64 allowedDirectories on the HTTP host\")\n  const directories = values.map(value => {\n    const path = resolvePath(value)\n    if (!lstatSync(path).isDirectory()) throw new ToolError(\"INVALID_INPUT\", \"allowedDirectories must contain directories\")\n    return path\n  })\n  return invocation => {\n    // Do not silently accept a configured boundary that has become a symlink.\n    if (directories.some(path => lstatSync(path).isSymbolicLink() || realpathSync(path) !== path || !lstatSync(path).isDirectory())) return false\n    const removesEntry = invocation.node === \"ai/filesystem/remove\" || invocation.node === \"ai/filesystem/rename\"\n    return invocation.paths.every(value => {\n      const path = resolvePath(value, {missing: true, finalSymlink: true})\n      return directories.some(directory => within(directory, path) && !(removesEntry && directory === path))\n    })\n  }\n}\n",
  "server/request/src/body.ts": "import {ToolError} from \"../../../shared/errors.ts\"\n\nconst MAX_REQUEST_BYTES = 12 * 1024 * 1024\n\nexport async function readBody(request: Request): Promise<unknown> {\n  if (request.headers.get(\"content-type\")?.split(\";\")[0]?.trim().toLowerCase() !== \"application/json\") throw new ToolError(\"UNSUPPORTED_MEDIA_TYPE\", \"Content-Type must be application/json\", 415)\n  const declared = request.headers.get(\"content-length\")\n  if (declared !== null) {\n    if (!/^\\d+$/.test(declared)) throw new ToolError(\"INVALID_INPUT\", \"Invalid Content-Length\")\n    if (Number(declared) > MAX_REQUEST_BYTES) throw new ToolError(\"LIMIT_EXCEEDED\", \"Request body exceeds 12 MiB\", 413)\n  }\n  if (request.body === null) return {}\n  const reader = request.body.getReader()\n  const chunks: Uint8Array[] = []\n  let bytes = 0\n  try {\n    while (true) {\n      const item = await reader.read()\n      if (item.done) break\n      bytes += item.value.byteLength\n      if (bytes > MAX_REQUEST_BYTES) {\n        await reader.cancel()\n        throw new ToolError(\"LIMIT_EXCEEDED\", \"Request body exceeds 12 MiB\", 413)\n      }\n      chunks.push(item.value)\n    }\n  } finally { reader.releaseLock() }\n  if (bytes === 0) return {}\n  try { return JSON.parse(new TextDecoder(\"utf-8\", {fatal: true}).decode(Buffer.concat(chunks, bytes))) }\n  catch { throw new ToolError(\"INVALID_INPUT\", \"Body must contain valid UTF-8 JSON\") }\n}\n",
  "shared/errors.ts": "export class ToolError extends Error {\n  readonly code: string\n  readonly status: number\n  readonly details?: unknown\n\n  constructor(code: string, message: string, status = 400, details?: unknown) {\n    super(message)\n    this.name = \"ToolError\"\n    this.code = code\n    this.status = status\n    this.details = details\n  }\n}\n\n/** Never disclose absolute paths or command output from an unexpected OS error. */\nexport function asToolError(error: unknown): ToolError {\n  if (error instanceof ToolError) return error\n  const code = (error as NodeJS.ErrnoException | null)?.code\n  if (code === \"ENOENT\") return new ToolError(\"NOT_FOUND\", \"The requested path does not exist\", 404)\n  if (code === \"EEXIST\" || code === \"ENOTEMPTY\") return new ToolError(\"CONFLICT\", \"The destination exists or the directory is not empty\", 409)\n  if (code === \"EACCES\" || code === \"EPERM\" || code === \"ELOOP\") return new ToolError(\"PATH_NOT_ALLOWED\", \"Access to this path is not permitted\", 403)\n  if (code === \"ENOTDIR\" || code === \"EISDIR\") return new ToolError(\"INVALID_PATH_TYPE\", \"The path has an incompatible type\", 400)\n  return new ToolError(\"INTERNAL_ERROR\", \"The operation failed\", 500)\n}\n",
  "shared/validation.ts": "import {ToolError} from \"./errors.ts\"\n\nexport function object(value: unknown, allowed: readonly string[]): void {\n  if (value === null || typeof value !== \"object\" || Array.isArray(value)) {\n    throw new ToolError(\"INVALID_INPUT\", \"Input must be an object\")\n  }\n  for (const key of Object.keys(value)) {\n    if (!allowed.includes(key)) throw new ToolError(\"INVALID_INPUT\", `Unknown field: ${key}`)\n  }\n}\n\nexport function text(value: unknown, label: string, empty = false): string {\n  if (typeof value !== \"string\" || (!empty && value.length === 0)) {\n    throw new ToolError(\"INVALID_INPUT\", `${label} must be ${empty ? \"a\" : \"a non-empty\"} string`)\n  }\n  return value\n}\n\nexport function integer(value: unknown, fallback: number, min: number, max: number, label: string): number {\n  if (value === undefined) return fallback\n  if (typeof value !== \"number\" || !Number.isSafeInteger(value) || value < min || value > max) {\n    throw new ToolError(\"INVALID_INPUT\", `${label} must be an integer in [${min}, ${max}]`)\n  }\n  return value\n}\n\nexport function boolean(value: unknown, fallback: boolean, label: string): boolean {\n  if (value === undefined) return fallback\n  if (typeof value !== \"boolean\") throw new ToolError(\"INVALID_INPUT\", `${label} must be a boolean`)\n  return value\n}\n\nexport function encoding(value: unknown): \"utf8\" | \"base64\" {\n  if (value === undefined || value === \"utf8\") return \"utf8\"\n  if (value === \"base64\") return \"base64\"\n  throw new ToolError(\"INVALID_INPUT\", \"encoding must be utf8 or base64\")\n}\n\nexport function hash(value: unknown): string | undefined {\n  if (value === undefined) return undefined\n  if (typeof value !== \"string\" || !/^[a-f0-9]{64}$/.test(value)) {\n    throw new ToolError(\"INVALID_INPUT\", \"expectedHash must be a lowercase SHA-256 hash\")\n  }\n  return value\n}\n",
  "tsconfig.json": "{\n  \"compilerOptions\": {\n    \"target\": \"ES2022\",\n    \"module\": \"NodeNext\",\n    \"moduleResolution\": \"NodeNext\",\n    \"strict\": true,\n    \"noEmit\": true,\n    \"allowImportingTsExtensions\": true,\n    \"verbatimModuleSyntax\": true,\n    \"noUncheckedIndexedAccess\": true,\n    \"skipLibCheck\": true,\n    \"types\": [\n      \"node\"\n    ]\n  },\n  \"include\": [\n    \"**/*.ts\"\n  ],\n  \"exclude\": [\n    \"node_modules\"\n  ]\n}\n",
  "VERIFICATION.md": "# Проверка универсального API\n\nИзменение подготовлено поверх 15cc36832aa570be7cbb8fa1fc76cd46a889e535 через GitHub.\nПроверочная копия выполнялась в изолированной среде, не на пользовательском Mac.\n\n## Выполнено\n\n- Node.js 22.16.0, TypeScript 5.8.3, @types/node 22.19.7.\n- tsc --noEmit: успешно.\n- npm run test:node: 85 тестов, 85 pass, 0 fail, 0 skip.\n- В том числе настоящий loopback HTTP listener на случайном порту, чтение файла\n  через fetch и закрытие listener в finally.\n\nФайловые/Git проверки охватывают абсолютные пути без регистрации, разные\nдиректории в batch/rename, byte budgets, hashes/conflicts, исключительное создание,\nправа файлов, symlink, .git как обычный каталог, dryRun, неоднозначные hunks,\nчастичный patch, имена Git с пробелами/переводами строк и отсутствие поиска в предках.\n\nПроверки dispatch/HTTP охватывают отсутствие roots/open, контракты/сценарии без\nисполнения, отказ при отсутствии/false/undefined/ошибке authorize, копирование и\nзаморозку аргументов при асинхронном разрешении, запрет подмены полномочий из input,\nфизические пути и оба конца rename, Bearer/Origin/body limits, старую конфигурацию,\nотсутствие input/секретов в логах и независимость результата от ошибки логирования.\n\n## Не проверено\n\nBun отсутствует: bun test не выполнен. Установка, актуальная машина Mac,\nживой ServiceClient Завхоза и пользовательские каталоги не проверялись.\nПолный прежний прогон 73 тестов не повторялся: тесты устаревших roots/open удалены,\nсохранённые сценарии адаптированы к новому API, добавлены проверки новой границы.\nУспешный commit не подменяет эти ограничения.\n\n## Сохранённое ограничение patch\n\nВ прежнем планировщике возможен конфликт между путями разных операций:\nAdd File: a, затем Add File: a/b. Он проявляется на фазе I/O после создания a.\nНовый сценарий проверяет реальный PARTIAL_FAILURE: completed содержит a,\ncurrent — a/b, cause — код отказа; ошибочный полный успех не возвращается.\nПланировщик не переписан. Для отдельного будущего исправления критерий — обнаружить\nэтот конфликт до первой записи и проверить отсутствие файлов после отказа.\n\nПроверки не доказывают безопасность против враждебных локальных гонок путей,\nмежпроцессный CAS, многофайловую атомарность, восстановление после отключения питания\nили отсутствие иных дефектов. Полномочия остаются ответственностью интегрирующего хоста.\n"
})
